import React from 'react';
import { Job } from '../types';
import { Briefcase, MapPin, Trash2, Bookmark, Archive, Zap, Users, Clock, Flame, CheckCircle2, MoreHorizontal } from 'lucide-react';

interface JobCardProps {
  job: Job;
  onOpenDetail: (job: Job, tab?: 'brief' | 'strategy') => void;
  onToggleStatus: (id: string, currentStatus: Job['status']) => void;
  onDelete: (id: string) => void;
  isKanban?: boolean;
  isSelected?: boolean;
  onSelect?: (id: string) => void;
  isSelectMode?: boolean;
}

const FollowUpTimer = ({ appliedDate }: { appliedDate?: string }) => {
    if (!appliedDate) return null;
    const applied = new Date(appliedDate);
    const now = new Date();
    const diffTime = now.getTime() - applied.getTime(); // Removed Math.abs to correctly calculate past time
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24)); 
    const followUpDay = 7;
    const remaining = followUpDay - diffDays;

    if (remaining <= 0) return <span className="text-[10px] font-bold text-red-500 flex items-center gap-1 animate-pulse bg-red-50 dark:bg-red-900/20 px-1.5 py-0.5 rounded"><Flame size={12} /> FOLLOW UP NOW</span>;
    return <span className="text-[10px] font-bold text-apple-gray flex items-center gap-1 bg-gray-100 dark:bg-white/10 px-1.5 py-0.5 rounded"><Clock size={10} /> {remaining}d left</span>;
};

const ScoreRing = ({ score }: { score: number }) => {
    const radius = 16;
    const circumference = 2 * Math.PI * radius;
    const offset = circumference - (score / 100) * circumference;

    let color = '#E5E5EA'; // Gray
    if (score >= 85) color = '#34C759'; // Green
    else if (score >= 70) color = '#0071e3'; // Blue
    else if (score >= 50) color = '#FFCC00'; // Yellow

    return (
        <div className="relative w-10 h-10 flex items-center justify-center">
            <svg className="w-full h-full transform -rotate-90" viewBox="0 0 40 40">
                <circle cx="20" cy="20" r={radius} stroke="currentColor" strokeWidth="3" fill="transparent" className="text-gray-200 dark:text-white/10" />
                <circle 
                    cx="20" 
                    cy="20" 
                    r={radius} 
                    stroke={color} 
                    strokeWidth="3" 
                    fill="transparent" 
                    strokeDasharray={circumference} 
                    strokeDashoffset={offset} 
                    strokeLinecap="round"
                />
            </svg>
            <span className="absolute text-[10px] font-bold text-apple-text dark:text-white">{score}</span>
        </div>
    );
};

const JobCard: React.FC<JobCardProps> = ({ job, onOpenDetail, onToggleStatus, onDelete, isKanban, isSelected, onSelect, isSelectMode }) => {
  const analysis = job.analysis;
  const status = job.status || 'new';
  const isSavedOrBetter = ['saved', 'applied', 'assessment', 'interview', 'offer'].includes(status);
  const score = analysis?.score || 0;

  // Kanban View: Compact, Information Dense
  if (isKanban) {
      return (
        <div 
            className="bg-white dark:bg-[#1C1C1E] rounded-[16px] p-4 cursor-pointer shadow-sm hover:shadow-md transition-all flex flex-col gap-3 border border-black/5 dark:border-white/5 hover:border-apple-blue/30 group"
            onClick={() => onOpenDetail(job)}
        >
            <div className="flex justify-between items-start gap-2">
                <h4 className="font-bold text-[13px] text-apple-text dark:text-white leading-snug line-clamp-2">{job.title}</h4>
                {score > 0 && (
                    <span className={`shrink-0 text-[10px] font-bold px-1.5 py-0.5 rounded ${score >= 80 ? 'bg-green-100 text-green-700 dark:bg-green-900/30' : 'bg-gray-100 text-gray-600 dark:bg-white/10'}`}>
                        {score}%
                    </span>
                )}
            </div>

            <div className="flex flex-col gap-1">
                <p className="text-[12px] text-apple-gray dark:text-gray-400 font-medium truncate">{job.company}</p>
                <div className="flex items-center gap-2">
                    {job.seniorityScore && (
                         <div className="flex items-center gap-1.5">
                            <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: job.seniorityScore === 'Senior' || job.seniorityScore === 'Lead' ? '#34C759' : '#FFCC00' }}></div>
                            <span className="text-[10px] text-apple-gray">{job.seniorityScore}</span>
                         </div>
                    )}
                </div>
            </div>

            {status === 'applied' && (
                <div className="pt-2 border-t border-gray-100 dark:border-white/5 mt-auto">
                    <FollowUpTimer appliedDate={job.appliedDate} />
                </div>
            )}
        </div>
      );
  }

  // Dashboard View: Rich Card
  return (
    <div 
        onClick={() => isSelectMode ? onSelect?.(job.id) : onOpenDetail(job)}
        className={`apple-card p-0 group cursor-pointer border relative transition-all duration-300 overflow-hidden flex flex-col
            ${isSelected ? 'ring-2 ring-apple-blue border-apple-blue transform scale-[1.01]' : 'border-black/5 dark:border-white/5'} 
            ${status === 'archived' ? 'opacity-60 grayscale' : 'bg-white dark:bg-[#1C1C1E]'}
        `}
    >
      {/* High Value Stripe */}
      {analysis?.isHighValue && <div className="h-1 w-full bg-gradient-to-r from-emerald-400 to-emerald-600"></div>}

      <div className="p-6 flex flex-col h-full">
          <div className="flex justify-between items-start mb-4">
             <div className="flex-1 pr-4">
                 <h3 className="text-[17px] font-bold tracking-tight text-apple-text dark:text-white group-hover:text-apple-blue transition-colors leading-tight mb-1.5">{job.title}</h3>
                 <div className="flex items-center gap-2 text-[13px] font-medium text-apple-gray dark:text-gray-400">
                    <span className="flex items-center gap-1.5 text-black dark:text-gray-200"><Briefcase size={12}/> {job.company}</span>
                    <span className="text-gray-300 dark:text-white/20">•</span>
                    <span className="flex items-center gap-1.5"><MapPin size={12}/> {job.location}</span>
                 </div>
             </div>

             {/* Score Visual or Selection Checkbox */}
             <div className="shrink-0">
                {isSelectMode ? (
                     <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${isSelected ? 'bg-apple-blue border-apple-blue text-white' : 'border-gray-300 dark:border-gray-600 bg-transparent'}`}>
                        {isSelected && <CheckCircle2 size={14} />}
                     </div>
                ) : (
                    <ScoreRing score={score} />
                )}
             </div>
          </div>

          <div className="flex flex-wrap items-center gap-2 mb-4">
            {job.seniorityScore && (
                 <span className="px-2.5 py-1 bg-gray-100 dark:bg-white/5 rounded-md text-[11px] font-semibold text-apple-gray dark:text-gray-300 flex items-center gap-1.5 border border-transparent dark:border-white/5">
                    <div className="w-1.5 h-1.5 rounded-full shadow-sm" style={{ backgroundColor: job.seniorityScore === 'Senior' || job.seniorityScore === 'Lead' ? '#34C759' : '#FFCC00' }}></div>
                    {job.seniorityScore}
                 </span>
            )}
            {analysis?.isHighValue && <span className="bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-400 text-[10px] font-bold px-2.5 py-1 rounded-md flex items-center gap-1 border border-emerald-100 dark:border-emerald-500/20"><Zap size={10} fill="currentColor"/> HIGH VALUE</span>}
            {status === 'applied' && <FollowUpTimer appliedDate={job.appliedDate} />}
          </div>

          <div className="mt-auto">
             <p className="text-[13px] text-gray-600 dark:text-gray-400 line-clamp-2 leading-relaxed opacity-90">{analysis?.verdict || job.summary}</p>
          </div>
      </div>

      {/* Floating Actions - Only visible on hover/focus */}
      <div className="absolute top-4 right-4 flex flex-col gap-2 opacity-0 group-hover:opacity-100 transition-all duration-200 translate-x-2 group-hover:translate-x-0 z-10">
         {!isSelectMode && status !== 'archived' && (
            <button 
                onClick={(e) => { e.stopPropagation(); onToggleStatus(job.id, status); }} 
                className={`w-8 h-8 flex items-center justify-center rounded-full shadow-lg border border-black/5 dark:border-white/10 transition-transform hover:scale-110 ${isSavedOrBetter ? 'bg-apple-blue text-white border-transparent' : 'bg-white dark:bg-[#2C2C2E] text-apple-gray'}`}
                title={isSavedOrBetter ? "Unsave" : "Save Job"}
            >
                <Bookmark size={14} fill={isSavedOrBetter ? "currentColor" : "none"} />
            </button>
         )}
         {!isSelectMode && (
             <button 
                onClick={(e) => { e.stopPropagation(); onDelete(job.id); }} 
                className="w-8 h-8 flex items-center justify-center rounded-full bg-white dark:bg-[#2C2C2E] border border-black/5 dark:border-white/10 shadow-lg text-apple-gray hover:bg-red-50 hover:text-red-500 hover:border-red-200 transition-all hover:scale-110"
                title="Archive/Delete"
             >
                {status === 'archived' ? <Trash2 size={14} /> : <Archive size={14} />}
             </button>
         )}
      </div>
    </div>
  );
};

export default JobCard;

import React, { useEffect, useState, useRef } from 'react';
import { X, ExternalLink, Briefcase, Zap, FileText, Sparkles, Edit2, Save, ChevronDown, RotateCw, TrendingUp, AlertTriangle, Loader2, Paperclip, Image as ImageIcon, Trash2, ChevronUp, Link as LinkIcon, Info, Check } from 'lucide-react';
import { Job, Attachment } from '../types';

interface JobDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  job: Job | null;
  onGenerateKit: (job: Job) => void;
  initialTab?: 'brief' | 'strategy';
  onUpdateJob?: (job: Job) => void;
  onReAnalyze?: (job: Job) => Promise<void>;
  onTailorResume?: (id: string) => void;
}

const JobDetailModal: React.FC<JobDetailModalProps> = ({ isOpen, onClose, job, onGenerateKit, initialTab = 'brief', onUpdateJob, onReAnalyze, onTailorResume }) => {
  const [activeTab, setActiveTab] = useState<'brief' | 'strategy'>(initialTab);
  const [isGeneratingKit, setIsGeneratingKit] = useState(false);
  const [isEditingSummary, setIsEditingSummary] = useState(false);
  const [editedSummary, setEditedSummary] = useState('');
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editedTitle, setEditedTitle] = useState('');
  const [isEditingCompany, setIsEditingCompany] = useState(false);
  const [editedCompany, setEditedCompany] = useState('');
  const notesRef = useRef<HTMLDivElement>(null);
  const [isEditingNotes, setIsEditingNotes] = useState(false); 
  const lastJobIdRef = useRef<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  useEffect(() => {
    setActiveTab(initialTab);
  }, [initialTab, isOpen, job]);

  useEffect(() => {
    if (job) {
        if (!isEditingSummary) setEditedSummary(job.summary || '');
        if (!isEditingTitle) setEditedTitle(job.title || '');
        if (!isEditingCompany) setEditedCompany(job.company || '');

        if (notesRef.current) {
            const isDifferentJob = lastJobIdRef.current !== job.id;
            if (isDifferentJob) {
                notesRef.current.innerHTML = job.notes || '';
                lastJobIdRef.current = job.id;
            } 
            else {
                const isActive = document.activeElement === notesRef.current;
                if (!isActive && job.notes !== notesRef.current.innerHTML) {
                    notesRef.current.innerHTML = job.notes || '';
                }
            }
        }
    }
  }, [job, isEditingSummary, isEditingTitle, isEditingCompany]);

  useEffect(() => {
      const timer = setTimeout(() => {
          if (isEditingSummary && onUpdateJob && job && editedSummary !== job.summary) {
              onUpdateJob({ ...job, summary: editedSummary });
          }
      }, 1000); 
      return () => clearTimeout(timer);
  }, [editedSummary, isEditingSummary, job, onUpdateJob]);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [isOpen]);

  if (!isOpen || !job) return null;

  const analysis = job.analysis;

  const applyUrl = job.url && job.url !== 'Manual Entry' ? (job.url.startsWith('http') ? job.url : `https://${job.url}`) : `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  const handleSaveTitle = () => { if (onUpdateJob && editedTitle.trim() !== job.title) onUpdateJob({ ...job, title: editedTitle }); setIsEditingTitle(false); };
  const handleSaveCompany = () => { if (onUpdateJob && editedCompany.trim() !== job.company) onUpdateJob({ ...job, company: editedCompany }); setIsEditingCompany(false); };
  const handleStatusChange = (e: React.ChangeEvent<HTMLSelectElement>) => { if (onUpdateJob) onUpdateJob({ ...job, status: e.target.value as Job['status'] }); };
  const handleReAnalyzeClick = async () => { if (onReAnalyze) { setIsAnalyzing(true); await onReAnalyze(job); setIsAnalyzing(false); } };
  const handleGenerateKitClick = async () => { setIsGeneratingKit(true); await onGenerateKit(job); setIsGeneratingKit(false); };
  const handleNotesUpdate = () => { if (notesRef.current && onUpdateJob) { const newNotes = notesRef.current.innerHTML; if (newNotes !== job.notes) onUpdateJob({ ...job, notes: newNotes }); } };
  const handleNotesBlur = () => { setIsEditingNotes(false); handleNotesUpdate(); };
  const handleNotesPaste = async (e: React.ClipboardEvent) => {
    const items = e.clipboardData.items;
    for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
            e.preventDefault();
            const blob = items[i].getAsFile();
            if (blob) {
                const reader = new FileReader();
                reader.onload = (ev) => {
                    const imgHtml = `<img src="${ev.target?.result}" style="max-width: 100%; border-radius: 8px; margin: 10px 0;" />`;
                    document.execCommand('insertHTML', false, imgHtml);
                    handleNotesUpdate();
                };
                reader.readAsDataURL(blob);
            }
            return;
        }
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-md transition-opacity" onClick={onClose}></div>
      <div className="relative bg-white dark:bg-[#1C1C1E] w-full max-w-6xl h-[92vh] flex flex-col shadow-2xl rounded-[24px] overflow-hidden animate-in zoom-in-95 duration-300 border border-transparent dark:border-white/10 ring-1 ring-black/5">

        {/* Header */}
        <div className="flex items-start justify-between px-8 py-8 shrink-0 border-b border-gray-100 dark:border-white/5 bg-white/50 dark:bg-[#1C1C1E]/50 backdrop-blur-xl z-20">
           <div className="flex-1 pr-8">
                <div className="flex items-center gap-2 mb-2">
                     {isEditingCompany ? (
                        <input 
                            value={editedCompany} 
                            onChange={(e) => setEditedCompany(e.target.value)} 
                            onBlur={handleSaveCompany} 
                            className="text-lg font-medium text-apple-gray bg-transparent border-b border-apple-blue outline-none" 
                            autoFocus 
                        />
                     ) : (
                        <span onClick={() => setIsEditingCompany(true)} className="text-lg font-medium text-apple-gray hover:text-apple-blue cursor-pointer transition-colors flex items-center gap-2">
                            {job.company}
                        </span>
                     )}
                     <span className="w-1 h-1 rounded-full bg-gray-300 dark:bg-gray-600"></span>
                     <span className="text-sm text-gray-400 font-medium">{job.location}</span>
                </div>

                {isEditingTitle ? (
                    <input value={editedTitle} onChange={(e) => setEditedTitle(e.target.value)} onBlur={handleSaveTitle} onKeyDown={(e) => e.key === 'Enter' && handleSaveTitle()} className="text-3xl font-bold tracking-tight text-apple-text dark:text-white w-full outline-none bg-transparent p-0 border-b-2 border-apple-blue" autoFocus />
                ) : (
                    <h2 onClick={() => setIsEditingTitle(true)} className="text-3xl font-bold tracking-tight text-apple-text dark:text-white leading-tight cursor-pointer hover:text-apple-blue transition-colors">{job.title}</h2>
                )}
           </div>

           <div className="flex items-center gap-3">
               <button onClick={onClose} className="w-10 h-10 flex items-center justify-center bg-gray-100 dark:bg-white/10 hover:bg-gray-200 dark:hover:bg-white/20 rounded-full transition-colors text-apple-text dark:text-white"><X size={20} /></button>
           </div>
        </div>

        {/* Content Body */}
        <div className="flex-1 overflow-hidden flex flex-col md:flex-row">
            {/* Left Column: Content */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-8 md:p-10 bg-white dark:bg-[#1C1C1E]">
                <div className="flex items-center gap-1 mb-8 bg-gray-100 dark:bg-white/5 p-1 rounded-xl w-fit border border-gray-200 dark:border-white/5">
                    <button onClick={() => setActiveTab('brief')} className={`px-6 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-all ${activeTab === 'brief' ? 'bg-white dark:bg-black text-black dark:text-white shadow-sm ring-1 ring-black/5' : 'text-gray-500 hover:text-black dark:hover:text-white'}`}>Overview</button>
                    <button onClick={() => { setActiveTab('strategy'); if (!analysis?.strategy) handleGenerateKitClick(); }} className={`px-6 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-all ${activeTab === 'strategy' ? 'bg-white dark:bg-black text-black dark:text-white shadow-sm ring-1 ring-black/5' : 'text-gray-500 hover:text-black dark:hover:text-white'}`}>Strategy Kit</button>
                </div>

                {activeTab === 'brief' ? (
                    <div className="animate-in fade-in slide-in-from-bottom-2 duration-300 space-y-10">
                        {/* Tags */}
                        <div className="flex flex-wrap gap-2">
                            {analysis?.isHighValue && <span className="px-3 py-1 rounded-md text-[11px] font-bold bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 border border-emerald-100 dark:border-emerald-800">High Priority</span>}
                            {job.seniorityScore && <span className="px-3 py-1 bg-gray-50 dark:bg-white/5 rounded-md text-[11px] font-bold text-gray-700 dark:text-gray-300 border border-gray-100 dark:border-white/5">{job.seniorityScore} Level</span>}
                            <span className="px-3 py-1 bg-gray-50 dark:bg-white/5 rounded-md text-[11px] font-bold text-gray-700 dark:text-gray-300 border border-gray-100 dark:border-white/5">{job.source}</span>
                        </div>

                        {/* Verdict */}
                        {analysis ? (
                            <div className="bg-gray-50 dark:bg-white/5 p-6 rounded-2xl border border-gray-100 dark:border-white/5">
                                <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-3 flex items-center gap-2"><Sparkles size={12} className="text-apple-blue"/> Strategic Verdict</h4>
                                <p className="text-xl text-apple-text dark:text-white font-medium leading-relaxed">{analysis.verdict}</p>
                            </div>
                        ) : (
                             <div className="p-6 bg-blue-50 dark:bg-blue-900/10 rounded-2xl border border-blue-100 dark:border-blue-800/30 flex items-center gap-3">
                                <Loader2 className="text-apple-blue animate-spin" size={20} />
                                <span className="text-sm font-semibold text-apple-blue">Analyzing opportunity potential...</span>
                             </div>
                        )}

                        {/* Summary Edit */}
                        <div>
                            <div className="flex items-center justify-between mb-3">
                                <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Role Description</h4>
                                <button onClick={() => setIsEditingSummary(!isEditingSummary)} className="text-[10px] font-bold text-apple-blue hover:text-blue-600 uppercase tracking-wider flex items-center gap-1">
                                    {isEditingSummary ? <Check size={12}/> : <Edit2 size={12}/>} {isEditingSummary ? 'Save Changes' : 'Edit Text'}
                                </button>
                            </div>
                            {isEditingSummary ? (
                                <textarea value={editedSummary} onChange={(e) => setEditedSummary(e.target.value)} className="w-full h-96 p-5 border-2 border-apple-blue rounded-xl text-sm leading-relaxed outline-none dark:bg-[#2C2C2E] dark:text-white font-mono focus:ring-4 focus:ring-apple-blue/10 transition-shadow" autoFocus />
                            ) : (
                                <div className="text-gray-700 dark:text-gray-300 text-[15px] leading-7 whitespace-pre-wrap">{job.summary}</div>
                            )}
                        </div>

                        {/* Notes */}
                        <div>
                            <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-3">Private Notes</h4>
                            <div className={`rounded-xl border transition-all bg-white dark:bg-[#2C2C2E] overflow-hidden ${isEditingNotes ? 'border-apple-blue ring-4 ring-apple-blue/5' : 'border-gray-200 dark:border-white/10'}`}>
                                <div ref={notesRef} contentEditable onFocus={() => setIsEditingNotes(true)} onBlur={handleNotesBlur} onInput={handleNotesUpdate} onPaste={handleNotesPaste} className="min-h-[150px] p-5 text-sm outline-none prose dark:prose-invert max-w-none empty:before:content-[attr(data-placeholder)] empty:before:text-gray-400" data-placeholder="Add your thoughts, tasks, or paste images here..." />
                            </div>
                        </div>
                    </div>
                ) : (
                    <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                         {isGeneratingKit ? (
                            <div className="flex flex-col items-center justify-center h-64 text-center space-y-4">
                                <Loader2 size={40} className="text-apple-blue animate-spin"/>
                                <p className="text-sm font-medium text-gray-500">Formulating application strategy...</p>
                            </div>
                        ) : (
                            <article className="prose prose-sm md:prose-base dark:prose-invert max-w-none prose-headings:font-bold prose-headings:tracking-tight prose-p:leading-relaxed prose-li:marker:text-apple-blue">
                                <div className="whitespace-pre-wrap">{analysis?.strategy || "Strategy formulation failed."}</div>
                            </article>
                        )}
                    </div>
                )}
            </div>

            {/* Right Column: Actions & Meta */}
            <div className="w-full md:w-[320px] bg-gray-50 dark:bg-[#111] border-l border-gray-200 dark:border-white/5 p-8 flex flex-col gap-8">

                {/* Status Card */}
                <div className="bg-white dark:bg-[#1C1C1E] p-1 rounded-2xl shadow-sm border border-gray-200 dark:border-white/5">
                    <div className="p-4 border-b border-gray-100 dark:border-white/5">
                        <label className="text-[10px] font-bold uppercase tracking-widest text-gray-400 mb-2 block">Current Status</label>
                        <div className="relative">
                            <select value={job.status || 'new'} onChange={handleStatusChange} className="w-full appearance-none bg-gray-50 dark:bg-black/20 hover:bg-gray-100 dark:hover:bg-black/40 px-4 py-3 rounded-xl font-bold text-sm text-apple-text dark:text-white cursor-pointer outline-none transition-colors">
                                <option value="saved">Saved</option>
                                <option value="applied">Applied</option>
                                <option value="interview">Interview</option>
                                <option value="offer">Offer</option>
                                <option value="archived">Archived</option>
                            </select>
                            <ChevronDown size={14} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" />
                        </div>
                    </div>

                    <div className="p-4 flex items-center justify-between">
                         <div>
                            <span className="text-[10px] font-bold uppercase tracking-widest text-gray-400 block mb-1">Match Score</span>
                            <span className={`text-2xl font-bold tracking-tight ${analysis?.score >= 80 ? 'text-green-600' : 'text-apple-text dark:text-white'}`}>{analysis?.score || 0}%</span>
                         </div>
                         <button onClick={handleReAnalyzeClick} className={`p-2 rounded-lg bg-gray-100 dark:bg-white/5 hover:bg-gray-200 dark:hover:bg-white/10 text-apple-blue transition-all ${isAnalyzing ? 'animate-spin' : ''}`} title="Re-Analyze">
                            <RotateCw size={16} />
                         </button>
                    </div>
                </div>

                {/* Resume Action */}
                <button onClick={() => onTailorResume?.(job.id)} className="group w-full py-4 bg-apple-text dark:bg-white text-white dark:text-black text-sm font-bold rounded-xl hover:scale-[1.02] active:scale-[0.98] transition-all shadow-xl shadow-black/5 flex items-center justify-center gap-2">
                    <Sparkles size={16} className="text-gray-400 group-hover:text-white dark:group-hover:text-black transition-colors" /> 
                    Open War Room
                </button>

                {/* Meta List */}
                <div className="space-y-6">
