import React from 'react';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer } from 'recharts';
import { Job } from '../types';

interface StatsPanelProps {
  jobs: Job[]; 
  selectedIndustry: string | null;
  onSelectIndustry: (industry: string | null) => void;
}

// Apple Data Colors - Adjusted for better contrast
const COLORS = [
  '#0071e3', // Blue
  '#ff2d55', // Pink
  '#ffcc00', // Yellow
  '#34c759', // Green
  '#af52de', // Purple
  '#5856d6', // Indigo
  '#8e8e93'  // Gray
];

const StatsPanel: React.FC<StatsPanelProps> = ({ jobs, selectedIndustry, onSelectIndustry }) => {
  const getIndustry = (job: Job): string => {
    if (job.analysis?.industry && job.analysis.industry !== "Other") {
        return job.analysis.industry;
    }
    const text = (job.company + " " + job.title + " " + (job.summary || "")).toLowerCase();
    if (text.match(/bank|finance|wealth|fintech/)) return 'Fintech';
    if (text.match(/insurance|underwrit/)) return 'Insurance';
    if (text.match(/gov|public|council|nhs/)) return 'Public Sector';
    if (text.match(/agency|studio/)) return 'Agency';
    return 'Tech';
  };

  const industryCounts = jobs.reduce((acc, job) => {
    const industry = getIndustry(job);
    acc[industry] = (acc[industry] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  const data = Object.entries(industryCounts)
    .map(([name, value]) => ({ name, value: value as number }))
    .filter((item) => item.value > 0)
    .sort((a, b) => b.value - a.value);

  const totalJobs = data.reduce((sum, item) => sum + item.value, 0);

  if (totalJobs === 0) return null;

  return (
    <div className="bg-white dark:bg-[#1C1C1E] rounded-xl p-4 border border-black/5 dark:border-white/5 shadow-sm">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-[11px] font-bold text-[#86868b] dark:text-[#98989D] uppercase tracking-wider">Market Breakdown</h3>
        {selectedIndustry && (
            <button 
                onClick={() => onSelectIndustry(null)}
                className="text-[10px] font-bold text-[#0071e3] dark:text-[#0A84FF] hover:underline"
            >
                Clear
            </button>
        )}
      </div>

      <div className="flex items-center gap-4">
          <div className="h-[100px] w-[100px] relative shrink-0">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie 
                    data={data} 
                    cx="50%" 
                    cy="50%" 
                    innerRadius={30} 
                    outerRadius={45} 
                    paddingAngle={3} 
                    dataKey="value" 
                    stroke="none" 
                    cornerRadius={3}
                    onClick={(data) => {
                        const newSelection = selectedIndustry === data.name ? null : data.name;
                        onSelectIndustry(newSelection);
                    }}
                >
                  {data.map((entry, index) => (
                    <Cell 
                        key={`cell-${index}`} 
                        fill={COLORS[index % COLORS.length]} 
                        opacity={selectedIndustry && selectedIndustry !== entry.name ? 0.3 : 1}
                        style={{ outline: 'none', transition: 'all 0.3s ease', cursor: 'pointer' }}
                    />
                  ))}
                </Pie>
                <Tooltip 
                  contentStyle={{ borderRadius: '8px', border: 'none', padding: '6px 10px', fontSize: '11px', boxShadow: '0 4px 12px rgba(0,0,0,0.1)', background: '#fff' }}
                  itemStyle={{ color: '#1d1d1f', fontWeight: 600 }}
                  separator=""
                  formatter={(value: number) => [value, '']}
                />
              </PieChart>
            </ResponsiveContainer>

            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                 <span className="text-lg font-bold text-[#1d1d1f] dark:text-[#f5f5f7] leading-none">{selectedIndustry ? data.find(d => d.name === selectedIndustry)?.value : totalJobs}</span>
            </div>
          </div>

          <div className="flex-1 space-y-1 min-w-0">
            {data.slice(0, 4).map((entry, index) => {
              const isSelected = selectedIndustry === entry.name;
              return (
                <button
                    key={entry.name} 
                    onClick={() => onSelectIndustry(isSelected ? null : entry.name)}
                    className={`w-full flex items-center justify-between text-[11px] cursor-pointer px-2 py-1 rounded-md transition-all ${isSelected ? 'bg-gray-100 dark:bg-white/10 font-bold text-[#1d1d1f] dark:text-white' : 'text-[#636366] dark:text-[#98989D] hover:bg-gray-50 dark:hover:bg-white/5'}`}
                >
                   <div className="flex items-center gap-2 min-w-0">
                     <div className="w-1.5 h-1.5 rounded-full shrink-0" style={{ backgroundColor: COLORS[index % COLORS.length] }}></div>
                     <span className="truncate">{entry.name}</span>
                   </div>
                   <span className="font-semibold tabular-nums opacity-60 ml-2">{entry.value}</span>
                </button>
              );
            })}
            {data.length > 4 && (
                <div className="text-[10px] text-gray-400 text-center pt-1">+ {data.length - 4} others</div>
            )}
          </div>
      </div>
    </div>
  );
};

