                     )}
                     <div className="relative" ref={profileMenuRef}>
                        <button onClick={() => setIsProfileMenuOpen(!isProfileMenuOpen)} className="w-8 h-8 rounded-full bg-gradient-to-br from-[#0071e3] to-[#5856d6] text-white flex items-center justify-center text-[10px] font-bold shadow-md hover:scale-105 transition-all focus:outline-none ring-2 ring-white dark:ring-black">VP</button>
