import React from 'react';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer } from 'recharts';
import { Job } from '../types';
import { Activity } from 'lucide-react';

interface StatsPanelProps {
  jobs: Job[]; 
  selectedIndustry: string | null;
  onSelectIndustry: (industry: string | null) => void;
}

// Apple Data Colors
const COLORS = [
  '#0071e3', // Blue
  '#ff2d55', // Pink
  '#ffcc00', // Yellow
  '#34c759', // Green
  '#af52de', // Purple
  '#5856d6', // Indigo
  '#8e8e93'  // Gray
];

const StatsPanel: React.FC<StatsPanelProps> = ({ jobs, selectedIndustry, onSelectIndustry }) => {
  const getIndustry = (job: Job): string => {
    if (job.analysis?.industry && job.analysis.industry !== "Other") {
        return job.analysis.industry;
    }
    const text = (job.company + " " + job.title + " " + (job.summary || "")).toLowerCase();
    if (text.match(/bank|finance|wealth|fintech/)) return 'Fintech';
    if (text.match(/insurance|underwrit/)) return 'Insurance';
    if (text.match(/gov|public|council|nhs/)) return 'Public Sector';
    if (text.match(/agency|studio/)) return 'Agency';
    return 'Tech';
  };

  const industryCounts = jobs.reduce((acc, job) => {
    const industry = getIndustry(job);
    acc[industry] = (acc[industry] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  const data = Object.entries(industryCounts)
    .map(([name, value]) => ({ name, value: value as number }))
    .filter((item) => item.value > 0)
    .sort((a, b) => b.value - a.value);

  const totalJobs = data.reduce((sum, item) => sum + item.value, 0);

  if (totalJobs === 0) return null;

  return (
    <div className="bg-white dark:bg-[#1C1C1E] rounded-[24px] p-5 border border-black/5 dark:border-white/10 shadow-lg shadow-black/5 flex flex-col h-full relative overflow-hidden group">
      {/* Background Gradient Effect */}
      <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500/5 rounded-full blur-3xl pointer-events-none"></div>

      <div className="flex items-center justify-between mb-4 z-10">
        <div className="flex items-center gap-2">
            <div className="p-1.5 bg-blue-50 dark:bg-blue-900/20 rounded-lg text-[#0071e3]">
                <Activity size={14} />
            </div>
            <h3 className="text-[11px] font-bold text-[#86868b] dark:text-[#98989D] uppercase tracking-wider">Market Radar</h3>
        </div>
        {selectedIndustry && (
            <button 
                onClick={() => onSelectIndustry(null)}
                className="text-[10px] font-bold text-[#0071e3] hover:bg-blue-50 dark:hover:bg-blue-900/20 px-2 py-1 rounded-md transition-colors"
            >
                Reset Filter
            </button>
        )}
      </div>

      <div className="flex items-center gap-4 flex-1">
          {/* Chart */}
          <div className="h-[100px] w-[100px] relative shrink-0">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie 
                    data={data} 
                    cx="50%" 
                    cy="50%" 
                    innerRadius={30} 
                    outerRadius={45} 
                    paddingAngle={4} 
                    dataKey="value" 
                    stroke="none" 
                    cornerRadius={4}
                    onClick={(data) => {
                        const newSelection = selectedIndustry === data.name ? null : data.name;
                        onSelectIndustry(newSelection);
                    }}
                    cursor="pointer"
                >
                  {data.map((entry, index) => (
                    <Cell 
                        key={`cell-${index}`} 
                        fill={COLORS[index % COLORS.length]} 
                        opacity={selectedIndustry && selectedIndustry !== entry.name ? 0.3 : 1}
                        style={{ outline: 'none', transition: 'all 0.3s ease' }}
                    />
                  ))}
                </Pie>
                <Tooltip 
                  contentStyle={{ borderRadius: '12px', border: 'none', padding: '8px 12px', fontSize: '11px', boxShadow: '0 10px 25px rgba(0,0,0,0.1)', background: '#fff' }}
                  itemStyle={{ color: '#1d1d1f', fontWeight: 600 }}
                  separator=""
                  formatter={(value: number) => [value, '']}
                />
              </PieChart>
            </ResponsiveContainer>

            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                 <span className="text-xl font-bold text-[#1d1d1f] dark:text-[#f5f5f7] leading-none tracking-tight">{selectedIndustry ? data.find(d => d.name === selectedIndustry)?.value : totalJobs}</span>
            </div>
          </div>

          {/* Legend - Grid Layout for compactness */}
          <div className="flex-1 grid grid-cols-2 gap-2 min-w-0">
            {data.slice(0, 4).map((entry, index) => {
              const isSelected = selectedIndustry === entry.name;
              return (
                <button
                    key={entry.name} 
                    onClick={() => onSelectIndustry(isSelected ? null : entry.name)}
                    className={`flex items-center gap-2 px-2 py-1.5 rounded-lg text-left transition-all ${isSelected ? 'bg-gray-100 dark:bg-white/10 ring-1 ring-black/5 dark:ring-white/10' : 'hover:bg-gray-50 dark:hover:bg-white/5'}`}
                >
                   <div className="w-2 h-2 rounded-full shrink-0 shadow-sm" style={{ backgroundColor: COLORS[index % COLORS.length] }}></div>
                   <div className="flex flex-col leading-none min-w-0">
                       <span className={`text-[10px] font-bold truncate ${isSelected ? 'text-black dark:text-white' : 'text-[#86868b] dark:text-gray-400'}`}>{entry.name}</span>
                       <span className="text-[9px] text-gray-400 font-medium tabular-nums">{Math.round((entry.value / totalJobs) * 100)}%</span>
                   </div>
                </button>
              );
            })}
          </div>
      </div>
    </div>
  );
};

export default StatsPanel;

