                                <button onClick={() => {setSpecialFilter('none'); setCityFilter('All'); setIndustryFilter(null); setSortBy('date');}} className="p-2 hover:bg-gray-100 dark:hover:bg-white/10 rounded-full transition-colors text-gray-500 focus-visible:ring-2 focus-visible:ring-[#0071e3] focus:outline-none" aria-label="Clear Filters" title="Clear Filters">
                                    <Filter size={16} />
                                </button>
                            </div>
                        </div>

                        {/* Bulk Action Bar */}
                        {isSelectMode && selectedJobIds.size > 0 && (
                            <div className="mb-8 p-4 bg-[#1d1d1f] dark:bg-white rounded-2xl shadow-xl flex items-center justify-between animate-in slide-in-from-top-4 duration-300 text-white dark:text-black mx-auto max-w-2xl sticky top-32 z-40 ring-1 ring-white/20">
                                <span className="text-sm font-bold pl-2">{selectedJobIds.size} selected</span>
                                <div className="flex items-center gap-3">
                                    <button onClick={handleBulkArchive} className="flex items-center gap-2 px-5 py-2.5 bg-white/10 dark:bg-black/10 rounded-full text-xs font-bold hover:bg-white/20 dark:hover:bg-black/20 transition-colors"><Archive size={14}/> Archive</button>
                                    <button onClick={handleBulkDelete} className="flex items-center gap-2 px-5 py-2.5 bg-[#FF3B30] text-white rounded-full text-xs font-bold hover:bg-[#D70015] transition-colors"><Trash2 size={14}/> Delete</button>
                                </div>
                            </div>
                        )}

                        {/* GRID */}
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 auto-rows-fr">
                            {filteredJobs.length === 0 ? (
                                <div className="col-span-full py-32 text-center">
                                    <div className="w-16 h-16 bg-gray-100 dark:bg-[#1C1C1E] rounded-full flex items-center justify-center mx-auto mb-4 text-gray-300 dark:text-gray-600"><Search size={24}/></div>
                                    <p className="text-sm font-bold text-gray-500">No opportunities found in this view.</p>
                                    <button onClick={() => {setSpecialFilter('none'); setCityFilter('All'); setIndustryFilter(null);}} className="mt-4 text-xs font-bold text-[#0071e3] hover:underline focus-visible:ring-2 focus-visible:ring-[#0071e3] focus:outline-none rounded">Clear Filters</button>
                                </div>
                            ) : (
                                filteredJobs.map(job => (
                                    <JobCard 
                                        key={job.id} 
                                        job={job} 
                                        onOpenDetail={handleOpenDetail} 
                                        onToggleStatus={toggleJobStatus} 
                                        onDelete={handleDelete} 
                                        isSelectMode={isSelectMode} 
                                        isSelected={selectedJobIds.has(job.id)} 
                                        onSelect={toggleJobSelection} 
                                    />
                                ))
                            )}
                        </div>
                    </>
                )}

                {currentView === ViewState.KANBAN && (
                    <div className="h-[calc(100vh-100px)] animate-fade-in-up flex flex-col w-full">
                        {/* PIPELINE COMMAND DECK */}
                        <div className="sticky top-[64px] z-30 -mx-6 px-6 py-4 bg-[#F5F5F7]/95 dark:bg-black/90 backdrop-blur-xl border-y border-black/5 dark:border-white/10 flex items-center justify-between gap-4 mb-2 shadow-sm transition-colors">
                            <div className="flex items-center gap-4">
                                <h1 className="text-2xl font-bold tracking-tight text-[#1d1d1f] dark:text-white">Pipeline</h1>
                                <div className="h-6 w-px bg-gray-300 dark:bg-white/10"></div>
                                <span className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider">{allJobs.filter(j => j.status !== 'archived' && j.status !== 'new').length} Active Opportunities</span>
                            </div>
                            <button onClick={() => setIsAddLinkOpen(true)} className="flex items-center gap-2 px-5 py-2 rounded-full bg-[#1d1d1f] dark:bg-white text-white dark:text-black text-xs font-bold hover:scale-105 transition-transform shadow-lg shadow-black/5 focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-[#1d1d1f] focus:outline-none">
                                <Plus size={14} /> Add Opportunity
                            </button>
                        </div>

                        <div className="flex-1 min-h-0 w-full pt-2">
                            <KanbanBoard jobs={allJobs} onGenerateKit={(job) => handleOpenDetail(job, 'strategy')} onToggleStatus={updateJobStatus} onDelete={handleDelete} onOpenDetail={handleOpenDetail} onOpenAddModal={() => setIsAddLinkOpen(true)}/>
                        </div>
                    </div>
                )}

                {currentView === ViewState.CV_EDITOR && (
                    <div className="h-[calc(100vh-80px)] animate-fade-in-up flex flex-col items-center">
                        {/* WAR ROOM COMMAND DECK */}
                        <div className="w-full sticky top-[64px] z-30 -mx-6 px-6 py-4 bg-[#F5F5F7]/95 dark:bg-black/90 backdrop-blur-xl border-y border-black/5 dark:border-white/10 flex items-center justify-between gap-4 mb-6 shadow-sm transition-colors">
                            <div className="flex items-center gap-4">
                                <h1 className="text-2xl font-bold tracking-tight text-[#1d1d1f] dark:text-white">Strategy Deck</h1>
                                {targetJobForEditor && (
                                     <>
                                        <div className="h-6 w-px bg-gray-300 dark:bg-white/10"></div>
                                        <div className="flex items-center gap-2 px-3 py-1 bg-blue-50 dark:bg-blue-900/20 rounded-full text-[#0071e3] text-xs font-bold border border-blue-100 dark:border-blue-500/20">
                                            <Briefcase size={12} /> Target: {targetJobForEditor.company}
                                        </div>
                                     </>
                                )}
                            </div>
                            <div className="flex items-center gap-2">
                                {/* Future actions like Export/Print can go here */}
                            </div>
                        </div>

                        <div className="flex-1 w-full relative">
                            <CVEditor targetJob={targetJobForEditor} allJobs={allJobs} />
                        </div>
                    </div>
                )}
            </div>
        </div>

      <JobDetailModal isOpen={modalOpen} onClose={() => setModalOpen(false)} job={selectedJob} onGenerateKit={handleGenerateKit} initialTab={initialModalTab} onUpdateJob={handleUpdateJob} onReAnalyze={handleReAnalyzeJob} onTailorResume={handleTailorResume}/>
      <AddLinkModal isOpen={isAddLinkOpen} onClose={() => setIsAddLinkOpen(false)} onAdd={handleAddManualJob} existingJobs={allJobs}/>
    </div>
  );
};

export default App;

import React, { useEffect, useState, useRef } from 'react';
import { X, ExternalLink, Briefcase, Zap, FileText, Sparkles, Edit2, Save, ChevronDown, RotateCw, TrendingUp, AlertTriangle, Loader2, Paperclip, Image as ImageIcon, Trash2, ChevronUp, Link as LinkIcon, Info, Check } from 'lucide-react';
import { Job, Attachment } from '../types';

interface JobDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  job: Job | null;
  onGenerateKit: (job: Job) => void;
  initialTab?: 'brief' | 'strategy';
  onUpdateJob?: (job: Job) => void;
  onReAnalyze?: (job: Job) => Promise<void>;
  onTailorResume?: (id: string) => void;
}

const JobDetailModal: React.FC<JobDetailModalProps> = ({ isOpen, onClose, job, onGenerateKit, initialTab = 'brief', onUpdateJob, onReAnalyze, onTailorResume }) => {
  const [activeTab, setActiveTab] = useState<'brief' | 'strategy'>(initialTab);
  const [isGeneratingKit, setIsGeneratingKit] = useState(false);
  const [isEditingSummary, setIsEditingSummary] = useState(false);
  const [editedSummary, setEditedSummary] = useState('');
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editedTitle, setEditedTitle] = useState('');
  const [isEditingCompany, setIsEditingCompany] = useState(false);
  const [editedCompany, setEditedCompany] = useState('');
  const notesRef = useRef<HTMLDivElement>(null);
  const [isEditingNotes, setIsEditingNotes] = useState(false); 
  const lastJobIdRef = useRef<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  useEffect(() => {
    setActiveTab(initialTab);
  }, [initialTab, isOpen, job]);

  useEffect(() => {
    if (job) {
        if (!isEditingSummary) setEditedSummary(job.summary || '');
        if (!isEditingTitle) setEditedTitle(job.title || '');
        if (!isEditingCompany) setEditedCompany(job.company || '');

        if (notesRef.current) {
            const isDifferentJob = lastJobIdRef.current !== job.id;
            if (isDifferentJob) {
                notesRef.current.innerHTML = job.notes || '';
                lastJobIdRef.current = job.id;
            } 
            else {
                const isActive = document.activeElement === notesRef.current;
                if (!isActive && job.notes !== notesRef.current.innerHTML) {
                    notesRef.current.innerHTML = job.notes || '';
                }
            }
        }
    }
  }, [job, isEditingSummary, isEditingTitle, isEditingCompany]);

  useEffect(() => {
      const timer = setTimeout(() => {
          if (isEditingSummary && onUpdateJob && job && editedSummary !== job.summary) {
              onUpdateJob({ ...job, summary: editedSummary });
          }
      }, 1000); 
      return () => clearTimeout(timer);
  }, [editedSummary, isEditingSummary, job, onUpdateJob]);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [isOpen]);

  if (!isOpen || !job) return null;

  const analysis = job.analysis;

  const applyUrl = job.url && job.url !== 'Manual Entry' ? (job.url.startsWith('http') ? job.url : `https://${job.url}`) : `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  const handleSaveTitle = () => { if (onUpdateJob && editedTitle.trim() !== job.title) onUpdateJob({ ...job, title: editedTitle }); setIsEditingTitle(false); };
  const handleSaveCompany = () => { if (onUpdateJob && editedCompany.trim() !== job.company) onUpdateJob({ ...job, company: editedCompany }); setIsEditingCompany(false); };
  const handleStatusChange = (e: React.ChangeEvent<HTMLSelectElement>) => { if (onUpdateJob) onUpdateJob({ ...job, status: e.target.value as Job['status'] }); };
  const handleReAnalyzeClick = async () => { if (onReAnalyze) { setIsAnalyzing(true); await onReAnalyze(job); setIsAnalyzing(false); } };
  const handleGenerateKitClick = async () => { setIsGeneratingKit(true); await onGenerateKit(job); setIsGeneratingKit(false); };
  const handleNotesUpdate = () => { if (notesRef.current && onUpdateJob) { const newNotes = notesRef.current.innerHTML; if (newNotes !== job.notes) onUpdateJob({ ...job, notes: newNotes }); } };
  const handleNotesBlur = () => { setIsEditingNotes(false); handleNotesUpdate(); };
  const handleNotesPaste = async (e: React.ClipboardEvent) => {
    const items = e.clipboardData.items;
    for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
            e.preventDefault();
            const blob = items[i].getAsFile();
            if (blob) {
                const reader = new FileReader();
                reader.onload = (ev) => {
                    const imgHtml = `<img src="${ev.target?.result}" style="max-width: 100%; border-radius: 8px; margin: 10px 0;" />`;
                    document.execCommand('insertHTML', false, imgHtml);
                    handleNotesUpdate();
                };
                reader.readAsDataURL(blob);
            }
            return;
        }
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6" role="dialog" aria-modal="true">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-md transition-opacity" onClick={onClose}></div>
      <div className="relative bg-white dark:bg-[#1C1C1E] w-full max-w-6xl h-[92vh] flex flex-col shadow-2xl rounded-[24px] overflow-hidden animate-in zoom-in-95 duration-300 border border-transparent dark:border-white/10 ring-1 ring-black/5">

        {/* Header */}
        <div className="flex items-start justify-between px-8 py-8 shrink-0 border-b border-gray-100 dark:border-white/5 bg-white/50 dark:bg-[#1C1C1E]/50 backdrop-blur-xl z-20">
           <div className="flex-1 pr-8">
                <div className="flex items-center gap-2 mb-2">
                     {isEditingCompany ? (
                        <input 
                            value={editedCompany} 
                            onChange={(e) => setEditedCompany(e.target.value)} 
                            onBlur={handleSaveCompany} 
                            className="text-lg font-medium text-gray-500 bg-transparent border-b border-apple-blue outline-none" 
                            autoFocus 
                            aria-label="Edit Company Name"
                        />
                     ) : (
                        <button onClick={() => setIsEditingCompany(true)} className="text-lg font-medium text-gray-500 hover:text-apple-blue cursor-pointer transition-colors flex items-center gap-2">
                            {job.company}
                        </button>
                     )}
                     <span className="w-1 h-1 rounded-full bg-gray-300 dark:bg-gray-600"></span>
                     <span className="text-sm text-gray-400 font-medium">{job.location}</span>
                </div>

                {isEditingTitle ? (
                    <input value={editedTitle} onChange={(e) => setEditedTitle(e.target.value)} onBlur={handleSaveTitle} onKeyDown={(e) => e.key === 'Enter' && handleSaveTitle()} className="text-3xl font-bold tracking-tight text-apple-text dark:text-white w-full outline-none bg-transparent p-0 border-b-2 border-apple-blue" autoFocus aria-label="Edit Job Title"/>
                ) : (
                    <h2 onClick={() => setIsEditingTitle(true)} className="text-3xl font-bold tracking-tight text-apple-text dark:text-white leading-tight cursor-pointer hover:text-apple-blue transition-colors">{job.title}</h2>
                )}
           </div>

           <div className="flex items-center gap-3">
               <button onClick={onClose} aria-label="Close Modal" className="w-10 h-10 flex items-center justify-center bg-gray-100 dark:bg-white/10 hover:bg-gray-200 dark:hover:bg-white/20 rounded-full transition-colors text-apple-text dark:text-white focus-visible:ring-2 focus-visible:ring-[#0071e3] focus:outline-none"><X size={20} /></button>
           </div>
        </div>

        {/* Content Body */}
        <div className="flex-1 overflow-hidden flex flex-col md:flex-row">
            {/* Left Column: Content */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-8 md:p-10 bg-white dark:bg-[#1C1C1E]">
                <div className="flex items-center gap-1 mb-8 bg-gray-100 dark:bg-white/5 p-1 rounded-xl w-fit border border-gray-200 dark:border-white/5">
                    <button onClick={() => setActiveTab('brief')} className={`px-6 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-all focus-visible:ring-2 focus-visible:ring-[#0071e3] focus:outline-none ${activeTab === 'brief' ? 'bg-white dark:bg-black text-black dark:text-white shadow-sm ring-1 ring-black/5' : 'text-gray-500 hover:text-black dark:hover:text-white'}`}>Overview</button>
                    <button onClick={() => { setActiveTab('strategy'); if (!analysis?.strategy) handleGenerateKitClick(); }} className={`px-6 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-all focus-visible:ring-2 focus-visible:ring-[#0071e3] focus:outline-none ${activeTab === 'strategy' ? 'bg-white dark:bg-black text-black dark:text-white shadow-sm ring-1 ring-black/5' : 'text-gray-500 hover:text-black dark:hover:text-white'}`}>Strategy Kit</button>
                </div>

                {activeTab === 'brief' ? (
                    <div className="animate-in fade-in slide-in-from-bottom-2 duration-300 space-y-10">
                        {/* Tags */}
                        <div className="flex flex-wrap gap-2">
                            {analysis?.isHighValue && <span className="px-3 py-1 rounded-md text-[11px] font-bold bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 border border-emerald-100 dark:border-emerald-800">High Priority</span>}
                            {job.seniorityScore && <span className="px-3 py-1 bg-gray-50 dark:bg-white/5 rounded-md text-[11px] font-bold text-gray-600 dark:text-gray-300 border border-gray-100 dark:border-white/5">{job.seniorityScore} Level</span>}
                            <span className="px-3 py-1 bg-gray-50 dark:bg-white/5 rounded-md text-[11px] font-bold text-gray-600 dark:text-gray-300 border border-gray-100 dark:border-white/5">{job.source}</span>
                        </div>

                        {/* Verdict */}
                        {analysis ? (
                            <div className="bg-gray-50 dark:bg-white/5 p-6 rounded-2xl border border-gray-100 dark:border-white/5">
                                <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-3 flex items-center gap-2"><Sparkles size={12} className="text-apple-blue"/> Strategic Verdict</h4>
                                <p className="text-xl text-apple-text dark:text-white font-medium leading-relaxed">{analysis.verdict}</p>
                            </div>
                        ) : (
                             <div className="p-6 bg-blue-50 dark:bg-blue-900/10 rounded-2xl border border-blue-100 dark:border-blue-800/30 flex items-center gap-3">
                                <Loader2 className="text-apple-blue animate-spin" size={20} />
                                <span className="text-sm font-semibold text-apple-blue">Analyzing opportunity potential...</span>
                             </div>
                        )}

                        {/* Summary Edit */}
                        <div>
                            <div className="flex items-center justify-between mb-3">
                                <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Role Description</h4>
                                <button onClick={() => setIsEditingSummary(!isEditingSummary)} className="text-[10px] font-bold text-apple-blue hover:text-blue-600 uppercase tracking-wider flex items-center gap-1 focus-visible:ring-2 focus-visible:ring-[#0071e3] focus:outline-none rounded">
                                    {isEditingSummary ? <Check size={12}/> : <Edit2 size={12}/>} {isEditingSummary ? 'Save Changes' : 'Edit Text'}
