                                <span className="text-sm font-bold pl-2">{selectedJobIds.size} selected</span>
                                <div className="flex items-center gap-3">
                                    <button onClick={handleBulkArchive} className="flex items-center gap-2 px-5 py-2.5 bg-white/10 dark:bg-black/10 rounded-full text-xs font-bold hover:bg-white/20 dark:hover:bg-black/20 transition-colors"><Archive size={14}/> Archive</button>
                                    <button onClick={handleBulkDelete} className="flex items-center gap-2 px-5 py-2.5 bg-[#FF3B30] text-white rounded-full text-xs font-bold hover:bg-[#D70015] transition-colors"><Trash2 size={14}/> Delete</button>
                                </div>
                            </div>
                        )}

                        {/* GRID */}
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 auto-rows-fr">
                            {filteredJobs.length === 0 ? (
                                <div className="col-span-full py-32 text-center">
                                    <div className="w-16 h-16 bg-gray-100 dark:bg-[#1C1C1E] rounded-full flex items-center justify-center mx-auto mb-4 text-gray-300 dark:text-gray-600"><Search size={24}/></div>
                                    <p className="text-sm font-bold text-gray-500">No opportunities found in this view.</p>
                                    <button onClick={() => {setSpecialFilter('none'); setCityFilter('All'); setIndustryFilter(null);}} className="mt-4 text-xs font-bold text-[#0071e3] hover:underline focus-visible:ring-2 focus-visible:ring-[#0071e3] focus:outline-none rounded">Clear Filters</button>
                                </div>
                            ) : (
                                filteredJobs.map(job => (
                                    <JobCard 
                                        key={job.id} 
                                        job={job} 
                                        onOpenDetail={handleOpenDetail} 
                                        onToggleStatus={toggleJobStatus} 
                                        onDelete={handleDelete} 
                                        isSelectMode={isSelectMode} 
                                        isSelected={selectedJobIds.has(job.id)} 
                                        onSelect={toggleJobSelection} 
                                    />
                                ))
                            )}
                        </div>
                    </div>
                )}

                {currentView === ViewState.KANBAN && (
                    <div className="h-full flex flex-col w-full">
                        {/* PIPELINE COMMAND DECK */}
                        <div className="px-6 py-4 bg-[#F5F5F7]/95 dark:bg-black/90 backdrop-blur-xl border-y border-black/5 dark:border-white/10 flex items-center justify-between gap-4 mb-2 shadow-sm transition-colors flex-none z-30">
                            <div className="flex items-center gap-4">
                                <h1 className="text-2xl font-bold tracking-tight text-[#1d1d1f] dark:text-white">Pipeline</h1>
                                <div className="h-6 w-px bg-gray-300 dark:bg-white/10"></div>
                                <span className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider">{allJobs.filter(j => j.status !== 'archived' && j.status !== 'new').length} Active Opportunities</span>
                            </div>
                            <button onClick={() => setIsAddLinkOpen(true)} className="flex items-center gap-2 px-5 py-2 rounded-full bg-[#1d1d1f] dark:bg-white text-white dark:text-black text-xs font-bold hover:scale-105 transition-transform shadow-lg shadow-black/5 focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-[#1d1d1f] focus:outline-none">
                                <Plus size={14} /> Add Opportunity
                            </button>
                        </div>

                        <div className="flex-1 min-h-0 w-full pt-2">
                            <KanbanBoard jobs={allJobs} onGenerateKit={(job) => handleOpenDetail(job, 'strategy')} onToggleStatus={updateJobStatus} onDelete={handleDelete} onOpenDetail={handleOpenDetail} onOpenAddModal={() => setIsAddLinkOpen(true)}/>
                        </div>
                    </div>
                )}

                {currentView === ViewState.CV_EDITOR && (
                    <div className="h-full flex flex-col items-center w-full">
                        {/* RESUME STUDIO COMMAND DECK */}
                        <div className="w-full px-6 py-4 bg-[#F5F5F7]/95 dark:bg-black/90 backdrop-blur-xl border-y border-black/5 dark:border-white/10 flex items-center justify-between gap-4 mb-6 shadow-sm transition-colors flex-none z-30">
                            <div className="flex items-center gap-4">
                                <h1 className="text-2xl font-bold tracking-tight text-[#1d1d1f] dark:text-white">Resume Studio</h1>
                                {targetJobForEditor && (
                                     <>
                                        <div className="h-6 w-px bg-gray-300 dark:bg-white/10"></div>
                                        <div className="flex items-center gap-2 px-3 py-1 bg-blue-50 dark:bg-blue-900/20 rounded-full text-[#0071e3] text-xs font-bold border border-blue-100 dark:border-blue-500/20">
                                            <Briefcase size={12} /> Target: {targetJobForEditor.company}
                                        </div>
                                     </>
                                )}
                            </div>
                            <div className="flex items-center gap-2">
                                {/* Future actions like Export/Print can go here */}
                            </div>
                        </div>

                        <div className="flex-1 w-full relative min-h-0">
                            <CVEditor targetJob={targetJobForEditor} allJobs={allJobs} />
                        </div>
                    </div>
                )}
            </div>
        </main>

      <JobDetailModal isOpen={modalOpen} onClose={() => setModalOpen(false)} job={selectedJob} onGenerateKit={handleGenerateKit} initialTab={initialModalTab} onUpdateJob={handleUpdateJob} onReAnalyze={handleReAnalyzeJob} onTailorResume={handleTailorResume}/>
      <AddLinkModal isOpen={isAddLinkOpen} onClose={() => setIsAddLinkOpen(false)} onAdd={handleAddManualJob} existingJobs={allJobs}/>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Bold, Italic, List, BookOpen, Trash, Sparkles, CheckCircle2, Book, MessageCircle, HelpCircle, ChevronRight, Wand2, Layout, Maximize2, Minimize2, RotateCcw, RotateCw, Pin, AlertTriangle, X, Type, Underline, Strikethrough, AlignLeft, AlignCenter, AlignRight, ListOrdered, Indent, Outdent, Heading1, Heading2, Heading3 } from 'lucide-react';
import { saveCV, getCV, saveJobCV } from '../services/firebase';
import { Job } from '../types';
import { USER_PROFILE } from '../constants';

interface CVEditorProps {
    targetJob?: Job | null;
    allJobs?: Job[]; // Passed for the Market Altimeter
}

const CVEditor: React.FC<CVEditorProps> = ({ targetJob, allJobs = [] }) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const [lastSaved, setLastSaved] = useState<string>('');
  const [showDoc, setShowDoc] = useState(false);
  const [isZenMode, setIsZenMode] = useState(false);
  const [foundKeywords, setFoundKeywords] = useState<Set<string>>(new Set());
  const [activeSidebarTab, setActiveSidebarTab] = useState<'strategy' | 'keywords' | 'snippets' | 'interview'>('strategy');
  const [currentFlashcard, setCurrentFlashcard] = useState(0);

  // SURGICAL PINS (Surgeon Ergonomics)
  // Allows pinning strategy items to the editor view to prevent context switching
  const [pinnedItems, setPinnedItems] = useState<string[]>([]);

  const keywords = useMemo(() => targetJob?.analysis?.matchedKeywords || [], [targetJob]);

  // MARKET ALTIMETER (Aviation Situational Awareness)
  // Alerts user of high-value opportunities while they are heads-down in the editor
  const highValueOpportunityCount = useMemo(() => {
      return allJobs.filter(j => (j.analysis?.score || 0) > 85 && j.status === 'new').length;
  }, [allJobs]);

  const scanKeywords = useCallback(() => {
    if (!editorRef.current || keywords.length === 0) return;
    const text = editorRef.current.innerText.toLowerCase();
    const found = new Set<string>();
    keywords.forEach(kw => {
        if (text.toLowerCase().includes(kw.toLowerCase())) found.add(kw);
    });
    setFoundKeywords(found);
  }, [keywords]);

  useEffect(() => {
    const loadContent = async () => {
        let content = "";
        if (targetJob) {
            content = targetJob.tailoredCv || await getCV();
        } else {
            content = await getCV();
        }

        if (editorRef.current) {
            editorRef.current.innerHTML = content || `
                <h1 style="font-size: 2.2em; font-weight: 800; margin-bottom: 0.2em; color: #1d1d1f; letter-spacing: -0.02em;">Senior UX Designer</h1>
                <p style="color: #86868b; font-size: 1.1em; margin-bottom: 2em; font-weight: 500;">Strategic and human-centered Senior UX Designer with 7+ years of experience transforming complex financial and insurance problems into intuitive digital solutions.</p>
                <h2 style="font-size: 1.4em; font-weight: 700; margin-top: 1.5em; margin-bottom: 0.8em; border-bottom: 2px solid #f5f5f7; padding-bottom: 0.3em;">Experience</h2>
            `;
            setLastSaved(targetJob ? 'Job Workspace' : 'Main CV');
            scanKeywords();
        }
    };
    loadContent();
  }, [targetJob?.id, scanKeywords]);

  const saveContent = useCallback(async () => {
    if (!editorRef.current) return;
    const html = editorRef.current.innerHTML;
    if (targetJob) {
        await saveJobCV(targetJob.id, html);
    } else {
        await saveCV(html);
    }
    const now = new Date();
    setLastSaved(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    scanKeywords();
  }, [targetJob, scanKeywords]);

  useEffect(() => {
      const handleInput = () => {
          const timeoutId = setTimeout(() => saveContent(), 1000);
          return () => clearTimeout(timeoutId);
      };
      const el = editorRef.current;
      el?.addEventListener('input', handleInput);
      return () => el?.removeEventListener('input', handleInput);
  }, [saveContent]);

  const execCmd = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    if (editorRef.current) editorRef.current.focus();
    saveContent();
  };

  const insertSnippet = (content: string) => {
      if (editorRef.current) {
          editorRef.current.focus();
          document.execCommand('insertHTML', false, `<p>${content}</p>`);
          saveContent();
      }
  };

  const togglePin = (content: string) => {
      setPinnedItems(prev => {
          if (prev.includes(content)) return prev.filter(p => p !== content);
          return [...prev, content];
      });
  };

  const keywordProgress = keywords.length > 0 ? (foundKeywords.size / keywords.length) * 100 : 0;
  const interviewQuestions = useMemo(() => {
      if (!targetJob?.analysis?.strategy) return ["How do you approach Design Systems?", "Describe your accessibility workflow.", "How do you handle stakeholder pushback?"];
      return targetJob.analysis.strategy.match(/\?.*$/gm) || ["Walk us through your Trove case study.", "How did you optimize compliance workflows at Intact?", "What is your UX philosophy?"];
  }, [targetJob]);

  const ToolBtn = ({ icon: Icon, cmd, val, title }: { icon: any, cmd: string, val?: string, title: string }) => (
      <button onClick={() => execCmd(cmd, val)} className="p-2 hover:bg-gray-100 dark:hover:bg-white/10 rounded-lg text-[#1d1d1f] dark:text-white transition-colors" title={title}>
          <Icon size={16} />
      </button>
  );

  return (
    <div className={`flex h-full gap-8 mx-auto relative px-6 pb-6 transition-all duration-500 ease-out ${isZenMode ? 'w-full max-w-none' : 'max-w-none w-full'}`}>

        {/* MARKET ALTIMETER (Aviation) */}
        {highValueOpportunityCount > 0 && (
            <div className="absolute top-0 right-6 -mt-16 bg-black/80 backdrop-blur-md text-white px-4 py-2 rounded-full text-xs font-bold flex items-center gap-2 animate-pulse cursor-pointer z-50 shadow-lg border border-white/10 hover:bg-black transition-colors">
                <AlertTriangle size={12} className="text-yellow-400" />
                MARKET ALERT: {highValueOpportunityCount} New High-Value Targets Detected
            </div>
        )}

        {/* WAR ROOM SIDEBAR */}
        {targetJob && !isZenMode && (
            <div className="w-[400px] shrink-0 flex flex-col gap-6 animate-in slide-in-from-left-12 duration-500 h-full">
                <div className="flex bg-[#E8E8ED] dark:bg-white/10 p-1.5 rounded-2xl w-full shrink-0">
                    <button onClick={() => setActiveSidebarTab('strategy')} className={`flex-1 flex items-center justify-center py-2.5 rounded-xl transition-all ${activeSidebarTab === 'strategy' ? 'bg-white dark:bg-[#1C1C1E] text-black dark:text-white shadow-sm font-medium' : 'text-[#86868b] hover:text-black dark:hover:text-white'}`} title="Strategy"><Sparkles size={18} /></button>
                    <button onClick={() => setActiveSidebarTab('keywords')} className={`flex-1 flex items-center justify-center py-2.5 rounded-xl transition-all ${activeSidebarTab === 'keywords' ? 'bg-white dark:bg-[#1C1C1E] text-black dark:text-white shadow-sm font-medium' : 'text-[#86868b] hover:text-black dark:hover:text-white'}`} title="Keywords"><Layout size={18} /></button>
                    <button onClick={() => setActiveSidebarTab('snippets')} className={`flex-1 flex items-center justify-center py-2.5 rounded-xl transition-all ${activeSidebarTab === 'snippets' ? 'bg-white dark:bg-[#1C1C1E] text-black dark:text-white shadow-sm font-medium' : 'text-[#86868b] hover:text-black dark:hover:text-white'}`} title="Snippets"><Book size={18} /></button>
                    <button onClick={() => setActiveSidebarTab('interview')} className={`flex-1 flex items-center justify-center py-2.5 rounded-xl transition-all ${activeSidebarTab === 'interview' ? 'bg-white dark:bg-[#1C1C1E] text-black dark:text-white shadow-sm font-medium' : 'text-[#86868b] hover:text-black dark:hover:text-white'}`} title="Interview Prep"><MessageCircle size={18} /></button>
                </div>

                <div className="flex-1 overflow-hidden bg-white dark:bg-[#1C1C1E] rounded-[32px] border border-black/5 dark:border-white/10 flex flex-col shadow-sm">
                    <div className="p-8 overflow-y-auto custom-scrollbar flex-1">

                        {activeSidebarTab === 'strategy' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                                <h3 className="text-sm font-bold uppercase tracking-widest text-[#86868b] mb-4">Live Strategy</h3>
                                <div className="prose prose-sm dark:prose-invert text-[14px] leading-relaxed whitespace-pre-wrap text-[#1d1d1f] dark:text-[#f5f5f7]">
                                    {targetJob.analysis?.strategy || "Generating custom strategy..."}
                                </div>
                                <div className="mt-6 pt-6 border-t border-dashed border-gray-200 dark:border-white/10">
                                    <button onClick={() => togglePin(targetJob.analysis?.verdict || "Focus on Value")} className="w-full py-3 bg-blue-50 dark:bg-blue-900/10 text-blue-600 dark:text-blue-400 rounded-xl text-xs font-bold flex items-center justify-center gap-2 hover:bg-blue-100 dark:hover:bg-blue-900/20 transition-colors"><Pin size={14}/> Pin Verdict to Editor</button>
                                </div>
                            </div>
                        )}

                        {activeSidebarTab === 'keywords' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                                <div className="flex items-center justify-between mb-4">
                                    <h3 className="text-sm font-bold uppercase tracking-widest text-[#86868b]">Keyword Gap</h3>
                                    <span className={`text-xs font-bold px-2 py-1 rounded-md ${keywordProgress >= 80 ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-600'}`}>{foundKeywords.size}/{keywords.length} Found</span>
                                </div>
                                <div className="w-full h-2 bg-gray-100 dark:bg-white/5 rounded-full mb-6 overflow-hidden">
                                    <div className="h-full bg-[#0071e3] transition-all duration-1000 ease-out" style={{ width: `${keywordProgress}%` }}></div>
                                </div>
                                <div className="space-y-2">
                                    {keywords.map(kw => {
                                        const isFound = foundKeywords.has(kw);
                                        return (
                                            <div key={kw} className={`group p-3 rounded-xl border transition-all flex items-center justify-between ${isFound ? 'bg-emerald-50 dark:bg-emerald-900/10 border-emerald-500/10 text-emerald-700 dark:text-emerald-400' : 'bg-gray-50 dark:bg-white/5 border-transparent text-[#1d1d1f] dark:text-white opacity-60'}`}>
                                                <span className="text-xs font-semibold">{kw}</span>
                                                {isFound ? <CheckCircle2 size={14} /> : <Wand2 size={14} className="opacity-0 group-hover:opacity-40" />}
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        )}

                        {activeSidebarTab === 'snippets' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                                <h3 className="text-sm font-bold uppercase tracking-widest text-[#86868b] mb-4">Case Studies</h3>
                                <div className="space-y-4">
                                    {USER_PROFILE.caseStudies.map((cs, i) => (
                                        <div key={i} className="group relative">
                                            <div onClick={() => insertSnippet(`${cs.title}: ${cs.description}`)} className="p-5 rounded-2xl bg-gray-50 dark:bg-white/5 hover:bg-white dark:hover:bg-[#2C2C2E] hover:shadow-lg hover:scale-[1.02] border border-transparent hover:border-black/5 transition-all cursor-pointer">
                                                <p className="text-[11px] font-bold uppercase tracking-wider text-[#0071e3] mb-2">{cs.title}</p>
                                                <p className="text-sm leading-snug text-[#1d1d1f] dark:text-white">{cs.description}</p>
                                            </div>
                                            <button onClick={(e) => { e.stopPropagation(); togglePin(`${cs.title}: ${cs.description}`); }} className="absolute top-2 right-2 p-1.5 rounded-full bg-white dark:bg-black shadow-md opacity-0 group-hover:opacity-100 transition-opacity text-[#86868b] hover:text-[#0071e3]"><Pin size={12}/></button>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {activeSidebarTab === 'interview' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2 duration-300 flex flex-col h-full">
                                <h3 className="text-sm font-bold uppercase tracking-widest text-[#86868b] mb-6">Prep Mode</h3>
                                <div className="flex-1 flex flex-col items-center justify-center">
                                    <div className="w-full aspect-[4/3] bg-gradient-to-br from-[#0071e3] to-[#5856d6] rounded-[24px] p-8 text-white flex flex-col shadow-2xl relative overflow-hidden group hover:scale-[1.02] transition-transform">
                                        <HelpCircle className="opacity-30 mb-auto" size={32} />
                                        <p className="text-xl font-bold leading-tight text-center mb-6">
                                            {interviewQuestions[currentFlashcard]}
                                        </p>
                                        <div className="mt-auto flex justify-center gap-2">
                                            {interviewQuestions.map((_, i) => (
                                                <div key={i} className={`w-1.5 h-1.5 rounded-full transition-all ${currentFlashcard === i ? 'bg-white scale-150' : 'bg-white/30'}`}></div>
                                            ))}
                                        </div>
                                    </div>
                                    <button 
                                        onClick={() => setCurrentFlashcard((currentFlashcard + 1) % interviewQuestions.length)}
                                        className="mt-8 px-6 py-3 bg-white dark:bg-[#2C2C2E] rounded-full text-sm font-bold text-[#1d1d1f] dark:text-white hover:shadow-lg transition-all flex items-center gap-2"
                                    >
                                        Next Question <ChevronRight size={16} />
                                    </button>
                                </div>
                            </div>
                        )}

                    </div>
                </div>
            </div>
        )}

        {/* EDITOR AREA with SURGICAL OVERLAYS */}
        <div className="flex-1 flex flex-col bg-white dark:bg-[#111] rounded-[32px] shadow-sm overflow-hidden border border-black/5 dark:border-white/10 relative h-full">

            {/* FLOATING PINNED ITEMS (Surgeon) */}
            {pinnedItems.length > 0 && (
                <div className="absolute top-24 right-8 w-72 flex flex-col gap-3 z-30 pointer-events-none">
                    {pinnedItems.map((item, i) => (
                        <div key={i} className="pointer-events-auto bg-[#FFF8C5] dark:bg-yellow-900/30 dark:text-yellow-100 p-4 rounded-xl shadow-xl border border-yellow-300/50 dark:border-yellow-500/20 text-[13px] leading-relaxed animate-in slide-in-from-right-8 fade-in duration-300 relative group backdrop-blur-sm">
                            <button onClick={() => togglePin(item)} className="absolute -top-2 -right-2 bg-white dark:bg-black rounded-full p-1 shadow-md opacity-0 group-hover:opacity-100 transition-opacity border border-black/5 hover:scale-110"><X size={12}/></button>
                            {item}
                        </div>
                    ))}
                </div>
            )}

            {/* Formatting Toolbar */}
            <div className="h-14 shrink-0 border-b border-black/5 dark:border-white/5 flex items-center px-6 justify-between bg-white/80 dark:bg-[#111]/80 backdrop-blur-xl z-20">
                <div className="flex items-center gap-1 overflow-x-auto no-scrollbar mask-linear-fade pr-4">
                    {targetJob && (
                        <button onClick={() => setIsZenMode(!isZenMode)} className="p-2 hover:bg-gray-100 dark:hover:bg-white/10 rounded-lg text-[#86868b] transition-all mr-2" title={isZenMode ? "Exit Zen Mode" : "Zen Mode"}>
                            {isZenMode ? <Minimize2 size={16} /> : <Maximize2 size={16} />}
                        </button>
                    )}

                    <div className="flex items-center gap-0.5 bg-gray-100/50 dark:bg-white/5 p-1 rounded-lg">
                        <ToolBtn icon={RotateCcw} cmd="undo" title="Undo" />
                        <ToolBtn icon={RotateCw} cmd="redo" title="Redo" />
                    </div>

                    <div className="w-px h-6 bg-gray-200 dark:bg-white/10 mx-2"></div>

                    <div className="flex items-center gap-0.5">
                        <ToolBtn icon={Bold} cmd="bold" title="Bold" />
                        <ToolBtn icon={Italic} cmd="italic" title="Italic" />
                        <ToolBtn icon={Underline} cmd="underline" title="Underline" />
                        <ToolBtn icon={Strikethrough} cmd="strikeThrough" title="Strikethrough" />
                    </div>

                    <div className="w-px h-6 bg-gray-200 dark:bg-white/10 mx-2"></div>

                    <div className="flex items-center gap-0.5">
                        <ToolBtn icon={Heading1} cmd="formatBlock" val="H1" title="Heading 1" />
                        <ToolBtn icon={Heading2} cmd="formatBlock" val="H2" title="Heading 2" />
                        <ToolBtn icon={Heading3} cmd="formatBlock" val="H3" title="Heading 3" />
                    </div>

                    <div className="w-px h-6 bg-gray-200 dark:bg-white/10 mx-2"></div>

                    <div className="flex items-center gap-0.5">
                        <ToolBtn icon={AlignLeft} cmd="justifyLeft" title="Align Left" />
                        <ToolBtn icon={AlignCenter} cmd="justifyCenter" title="Align Center" />
                        <ToolBtn icon={AlignRight} cmd="justifyRight" title="Align Right" />
                    </div>

                    <div className="w-px h-6 bg-gray-200 dark:bg-white/10 mx-2"></div>

                    <div className="flex items-center gap-0.5">
                        <ToolBtn icon={List} cmd="insertUnorderedList" title="Bullet List" />
                        <ToolBtn icon={ListOrdered} cmd="insertOrderedList" title="Numbered List" />
                        <ToolBtn icon={Indent} cmd="indent" title="Indent" />
                        <ToolBtn icon={Outdent} cmd="outdent" title="Outdent" />
                    </div>
                </div>

                <div className="flex items-center gap-4 shrink-0">
                    <button onClick={() => setShowDoc(!showDoc)} className={`h-8 px-4 rounded-full transition-all flex items-center gap-2 text-[12px] font-bold ${showDoc ? 'bg-[#1d1d1f] dark:bg-white text-white dark:text-black shadow-lg' : 'bg-gray-100 dark:bg-white/10 text-[#1d1d1f] dark:text-white'}`}>
                        <BookOpen size={14} /> Ref CV
                    </button>
                    <div className="text-[10px] font-bold text-[#86868b] bg-gray-50 dark:bg-white/5 px-3 py-1.5 rounded-full border border-black/5 dark:border-white/5 tabular-nums">
                        {lastSaved || 'Unsaved'}
                    </div>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto bg-[#F5F5F7] dark:bg-[#000] flex relative custom-scrollbar">
                {showDoc && (
                    <div className="w-1/2 h-full border-r border-black/5 dark:border-white/10 bg-white dark:bg-[#1C1C1E] hidden lg:block animate-in slide-in-from-left-8 duration-500 ease-out z-10 shadow-2xl sticky top-0">
                        <iframe src="https://docs.google.com/document/d/1RcERxf9--nMGdxXTHAt4q35yynk39Aqk31AqSuG02G4/preview" className="w-full h-full border-none" title="Reference CV"></iframe>
                    </div>
                )}
                <div className={`flex-1 flex justify-center p-12 transition-all duration-500 ${showDoc || targetJob ? 'bg-gray-100 dark:bg-[#000]' : ''}`}>
                     <div 
                        ref={editorRef} 
                        contentEditable 
                        role="textbox" 
                        aria-multiline="true" 
                        className={`w-full h-max min-h-[1100px] bg-white text-[#1d1d1f] shadow-2xl p-[80px] outline-none font-sans text-[11pt] leading-[1.6] transition-all duration-300 rounded-sm mb-32 ${isZenMode ? 'max-w-[1000px]' : (showDoc || targetJob ? 'max-w-full' : 'max-w-[850px]')}`}
                     />
                </div>
            </div>
        </div>
    </div>
  );
};

export default CVEditor;

import React, { useEffect, useState, useRef } from 'react';
import { X, ExternalLink, Briefcase, Zap, FileText, Sparkles, Edit2, Save, ChevronDown, RotateCw, TrendingUp, AlertTriangle, Loader2, Paperclip, Image as ImageIcon, Trash2, ChevronUp, Link as LinkIcon, Info, Check } from 'lucide-react';
import { Job, Attachment } from '../types';

interface JobDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  job: Job | null;
  onGenerateKit: (job: Job) => void;
  initialTab?: 'brief' | 'strategy';
  onUpdateJob?: (job: Job) => void;
  onReAnalyze?: (job: Job) => Promise<void>;
  onTailorResume?: (id: string) => void;
}

const JobDetailModal: React.FC<JobDetailModalProps> = ({ isOpen, onClose, job, onGenerateKit, initialTab = 'brief', onUpdateJob, onReAnalyze, onTailorResume }) => {
  const [activeTab, setActiveTab] = useState<'brief' | 'strategy'>(initialTab);
  const [isGeneratingKit, setIsGeneratingKit] = useState(false);
  const [isEditingSummary, setIsEditingSummary] = useState(false);
  const [editedSummary, setEditedSummary] = useState('');
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editedTitle, setEditedTitle] = useState('');
  const [isEditingCompany, setIsEditingCompany] = useState(false);
  const [editedCompany, setEditedCompany] = useState('');
  const notesRef = useRef<HTMLDivElement>(null);
  const [isEditingNotes, setIsEditingNotes] = useState(false); 
  const lastJobIdRef = useRef<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  useEffect(() => {
    setActiveTab(initialTab);
  }, [initialTab, isOpen, job]);

  useEffect(() => {
    if (job) {
        if (!isEditingSummary) setEditedSummary(job.summary || '');
        if (!isEditingTitle) setEditedTitle(job.title || '');
        if (!isEditingCompany) setEditedCompany(job.company || '');

        if (notesRef.current) {
            const isDifferentJob = lastJobIdRef.current !== job.id;
            if (isDifferentJob) {
                notesRef.current.innerHTML = job.notes || '';
                lastJobIdRef.current = job.id;
            } 
            else {
                const isActive = document.activeElement === notesRef.current;
                if (!isActive && job.notes !== notesRef.current.innerHTML) {
                    notesRef.current.innerHTML = job.notes || '';
                }
            }
        }
    }
  }, [job, isEditingSummary, isEditingTitle, isEditingCompany]);

  useEffect(() => {
      const timer = setTimeout(() => {
          if (isEditingSummary && onUpdateJob && job && editedSummary !== job.summary) {
              onUpdateJob({ ...job, summary: editedSummary });
          }
      }, 1000); 
      return () => clearTimeout(timer);
  }, [editedSummary, isEditingSummary, job, onUpdateJob]);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [isOpen]);

  if (!isOpen || !job) return null;

  const analysis = job.analysis;

  const applyUrl = job.url && job.url !== 'Manual Entry' ? (job.url.startsWith('http') ? job.url : `https://${job.url}`) : `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  const handleSaveTitle = () => { if (onUpdateJob && editedTitle.trim() !== job.title) onUpdateJob({ ...job, title: editedTitle }); setIsEditingTitle(false); };
  const handleSaveCompany = () => { if (onUpdateJob && editedCompany.trim() !== job.company) onUpdateJob({ ...job, company: editedCompany }); setIsEditingCompany(false); };
  const handleStatusChange = (e: React.ChangeEvent<HTMLSelectElement>) => { if (onUpdateJob) onUpdateJob({ ...job, status: e.target.value as Job['status'] }); };
  const handleReAnalyzeClick = async () => { if (onReAnalyze) { setIsAnalyzing(true); await onReAnalyze(job); setIsAnalyzing(false); } };
  const handleGenerateKitClick = async () => { setIsGeneratingKit(true); await onGenerateKit(job); setIsGeneratingKit(false); };
  const handleNotesUpdate = () => { if (notesRef.current && onUpdateJob) { const newNotes = notesRef.current.innerHTML; if (newNotes !== job.notes) onUpdateJob({ ...job, notes: newNotes }); } };
  const handleNotesBlur = () => { setIsEditingNotes(false); handleNotesUpdate(); };
  const handleNotesPaste = async (e: React.ClipboardEvent) => {
    const items = e.clipboardData.items;
    for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
            e.preventDefault();
            const blob = items[i].getAsFile();
            if (blob) {
                const reader = new FileReader();
                reader.onload = (ev) => {
                    const imgHtml = `<img src="${ev.target?.result}" style="max-width: 100%; border-radius: 8px; margin: 10px 0;" />`;
                    document.execCommand('insertHTML', false, imgHtml);
                    handleNotesUpdate();
                };
                reader.readAsDataURL(blob);
            }
            return;
        }
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6" role="dialog" aria-modal="true">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-md transition-opacity" onClick={onClose}></div>
      <div className="relative bg-white dark:bg-[#1C1C1E] w-full max-w-6xl h-[92vh] flex flex-col shadow-2xl rounded-[24px] overflow-hidden animate-in zoom-in-95 duration-300 border border-transparent dark:border-white/10 ring-1 ring-black/5">

        {/* Header */}
        <div className="flex items-start justify-between px-8 py-8 shrink-0 border-b border-gray-100 dark:border-white/5 bg-white/50 dark:bg-[#1C1C1E]/50 backdrop-blur-xl z-20">
           <div className="flex-1 pr-8">
                <div className="flex items-center gap-2 mb-2">
                     {isEditingCompany ? (
                        <input 
                            value={editedCompany} 
                            onChange={(e) => setEditedCompany(e.target.value)} 
                            onBlur={handleSaveCompany} 
                            className="text-lg font-medium text-gray-500 bg-transparent border-b border-apple-blue outline-none" 
                            autoFocus 
                            aria-label="Edit Company Name"
                        />
                     ) : (
                        <button onClick={() => setIsEditingCompany(true)} className="text-lg font-medium text-gray-500 hover:text-apple-blue cursor-pointer transition-colors flex items-center gap-2">
                            {job.company}
                        </button>
                     )}
                     <span className="w-1 h-1 rounded-full bg-gray-300 dark:bg-gray-600"></span>
                     <span className="text-sm text-gray-400 font-medium">{job.location}</span>
                </div>

                {isEditingTitle ? (
                    <input value={editedTitle} onChange={(e) => setEditedTitle(e.target.value)} onBlur={handleSaveTitle} onKeyDown={(e) => e.key === 'Enter' && handleSaveTitle()} className="text-3xl font-bold tracking-tight text-apple-text dark:text-white w-full outline-none bg-transparent p-0 border-b-2 border-apple-blue" autoFocus aria-label="Edit Job Title"/>
                ) : (
                    <h2 onClick={() => setIsEditingTitle(true)} className="text-3xl font-bold tracking-tight text-apple-text dark:text-white leading-tight cursor-pointer hover:text-apple-blue transition-colors">{job.title}</h2>
                )}
           </div>

           <div className="flex items-center gap-3">
               <button onClick={onClose} aria-label="Close Modal" className="w-10 h-10 flex items-center justify-center bg-gray-100 dark:bg-white/10 hover:bg-gray-200 dark:hover:bg-white/20 rounded-full transition-colors text-apple-text dark:text-white focus-visible:ring-2 focus-visible:ring-[#0071e3] focus:outline-none"><X size={20} /></button>
           </div>
        </div>

        {/* Content Body */}
        <div className="flex-1 overflow-hidden flex flex-col md:flex-row">
            {/* Left Column: Content */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-8 md:p-10 bg-white dark:bg-[#1C1C1E]">
                <div className="flex items-center gap-1 mb-8 bg-gray-100 dark:bg-white/5 p-1 rounded-xl w-fit border border-gray-200 dark:border-white/5">
                    <button onClick={() => setActiveTab('brief')} className={`px-6 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-all focus-visible:ring-2 focus-visible:ring-[#0071e3] focus:outline-none ${activeTab === 'brief' ? 'bg-white dark:bg-black text-black dark:text-white shadow-sm ring-1 ring-black/5' : 'text-gray-500 hover:text-black dark:hover:text-white'}`}>Overview</button>
                    <button onClick={() => { setActiveTab('strategy'); if (!analysis?.strategy) handleGenerateKitClick(); }} className={`px-6 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-all focus-visible:ring-2 focus-visible:ring-[#0071e3] focus:outline-none ${activeTab === 'strategy' ? 'bg-white dark:bg-black text-black dark:text-white shadow-sm ring-1 ring-black/5' : 'text-gray-500 hover:text-black dark:hover:text-white'}`}>Strategy Kit</button>
                </div>

                {activeTab === 'brief' ? (
                    <div className="animate-in fade-in slide-in-from-bottom-2 duration-300 space-y-10">
                        {/* Tags */}
                        <div className="flex flex-wrap gap-2">
                            {analysis?.isHighValue && <span className="px-3 py-1 rounded-md text-[11px] font-bold bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 border border-emerald-100 dark:border-emerald-800">High Priority</span>}
                            {job.seniorityScore && <span className="px-3 py-1 bg-gray-50 dark:bg-white/5 rounded-md text-[11px] font-bold text-gray-600 dark:text-gray-300 border border-gray-100 dark:border-white/5">{job.seniorityScore} Level</span>}
                            <span className="px-3 py-1 bg-gray-50 dark:bg-white/5 rounded-md text-[11px] font-bold text-gray-600 dark:text-gray-300 border border-gray-100 dark:border-white/5">{job.source}</span>
                        </div>

                        {/* Verdict */}
                        {analysis ? (
                            <div className="bg-gray-50 dark:bg-white/5 p-6 rounded-2xl border border-gray-100 dark:border-white/5">
                                <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-3 flex items-center gap-2"><Sparkles size={12} className="text-apple-blue"/> Strategic Verdict</h4>
                                <p className="text-xl text-apple-text dark:text-white font-medium leading-relaxed">{analysis.verdict}</p>
                            </div>
                        ) : (
                             <div className="p-6 bg-blue-50 dark:bg-blue-900/10 rounded-2xl border border-blue-100 dark:border-blue-800/30 flex items-center gap-3">
                                <Loader2 className="text-apple-blue animate-spin" size={20} />
                                <span className="text-sm font-semibold text-apple-blue">Analyzing opportunity potential...</span>
                             </div>
                        )}

                        {/* Summary Edit */}
                        <div>
                            <div className="flex items-center justify-between mb-3">
                                <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Role Description</h4>
                                <button onClick={() => setIsEditingSummary(!isEditingSummary)} className="text-[10px] font-bold text-apple-blue hover:text-blue-600 uppercase tracking-wider flex items-center gap-1 focus-visible:ring-2 focus-visible:ring-[#0071e3] focus:outline-none rounded">
                                    {isEditingSummary ? <Check size={12}/> : <Edit2 size={12}/>} {isEditingSummary ? 'Save Changes' : 'Edit Text'}
                                </button>
                            </div>
                            {isEditingSummary ? (
                                <textarea value={editedSummary} onChange={(e) => setEditedSummary(e.target.value)} className="w-full h-96 p-5 border-2 border-apple-blue rounded-xl text-sm leading-relaxed outline-none dark:bg-[#2C2C2E] dark:text-white font-mono focus:ring-4 focus:ring-apple-blue/10 transition-shadow" autoFocus aria-label="Edit Job Summary" />
                            ) : (
                                <div className="text-gray-600 dark:text-gray-300 text-[15px] leading-7 whitespace-pre-wrap">{job.summary}</div>
                            )}
                        </div>

                        {/* Notes */}
                        <div>
                            <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-3">Private Notes</h4>
                            <div className={`rounded-xl border transition-all bg-white dark:bg-[#2C2C2E] overflow-hidden ${isEditingNotes ? 'border-apple-blue ring-4 ring-apple-blue/5' : 'border-gray-200 dark:border-white/10'}`}>
                                <div ref={notesRef} contentEditable onFocus={() => setIsEditingNotes(true)} onBlur={handleNotesBlur} onInput={handleNotesUpdate} onPaste={handleNotesPaste} className="min-h-[150px] p-5 text-sm outline-none prose dark:prose-invert max-w-none empty:before:content-[attr(data-placeholder)] empty:before:text-gray-400 text-gray-600 dark:text-gray-300" data-placeholder="Add your thoughts, tasks, or paste images here..." role="textbox" aria-label="Private Notes" />
                            </div>
                        </div>
                    </div>
                ) : (
                    <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                         {isGeneratingKit ? (
                            <div className="flex flex-col items-center justify-center h-64 text-center space-y-4">
                                <Loader2 size={40} className="text-apple-blue animate-spin"/>
                                <p className="text-sm font-medium text-gray-500">Formulating application strategy...</p>
                            </div>
                        ) : (
                            <article className="prose prose-sm md:prose-base dark:prose-invert max-w-none prose-headings:font-bold prose-headings:tracking-tight prose-p:leading-relaxed prose-li:marker:text-apple-blue text-gray-600 dark:text-gray-300">
                                <div className="whitespace-pre-wrap">{analysis?.strategy || "Strategy formulation failed."}</div>
                            </article>
                        )}
                    </div>
                )}
            </div>

            {/* Right Column: Actions & Meta */}
            <div className="w-full md:w-[320px] bg-gray-50 dark:bg-[#111] border-l border-gray-200 dark:border-white/5 p-8 flex flex-col gap-8">

                {/* Status Card */}
                <div className="bg-white dark:bg-[#1C1C1E] p-1 rounded-2xl shadow-sm border border-gray-200 dark:border-white/5">
                    <div className="p-4 border-b border-gray-100 dark:border-white/5">
                        <label className="text-[10px] font-bold uppercase tracking-widest text-gray-400 mb-2 block">Current Status</label>
                        <div className="relative">
                            <select value={job.status || 'new'} onChange={handleStatusChange} className="w-full appearance-none bg-gray-50 dark:bg-black/20 hover:bg-gray-100 dark:hover:bg-black/40 px-4 py-3 rounded-xl font-bold text-sm text-apple-text dark:text-white cursor-pointer outline-none transition-colors focus-visible:ring-2 focus-visible:ring-[#0071e3]">
                                <option value="saved">Saved</option>
                                <option value="applied">Applied</option>
                                <option value="interview">Interview</option>
                                <option value="offer">Offer</option>
                                <option value="archived">Archived</option>
                            </select>
                            <ChevronDown size={14} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" />
                        </div>
                    </div>

                    <div className="p-4 flex items-center justify-between">
                         <div>
                            <span className="text-[10px] font-bold uppercase tracking-widest text-gray-400 block mb-1">Match Score</span>
