                                </div>
                                <div className="w-full h-2 bg-gray-100 dark:bg-white/5 rounded-full mb-6 overflow-hidden">
                                    <div className="h-full bg-[#0071e3] transition-all duration-1000 ease-out" style={{ width: `${keywordProgress}%` }}></div>
