import React, { useState } from 'react';
import { Job } from '../types';
import JobCard from './JobCard';
import { Bookmark, Send, Users, Trophy, ClipboardList, Plus } from 'lucide-react';

interface KanbanBoardProps {
  jobs: Job[];
  onGenerateKit: (job: Job) => void;
  onToggleStatus: (id: string, status: Job['status']) => void;
  onDelete: (id: string) => void;
  onOpenDetail: (job: Job) => void;
  onOpenAddModal: () => void;
}

const KanbanBoard: React.FC<KanbanBoardProps> = ({ jobs, onGenerateKit, onToggleStatus, onDelete, onOpenDetail, onOpenAddModal }) => {
  const [draggedJobId, setDraggedJobId] = useState<string | null>(null);

  const columns: { id: Job['status'], title: string, icon: React.ReactNode, count: number, color: string }[] = [
      { id: 'saved', title: 'Saved', icon: <Bookmark size={14} />, count: jobs.filter(j => j.status === 'saved').length, color: 'bg-gray-500' },
      { id: 'applied', title: 'Applied', icon: <Send size={14} />, count: jobs.filter(j => j.status === 'applied').length, color: 'bg-blue-500' },
      { id: 'assessment', title: 'Assessment', icon: <ClipboardList size={14} />, count: jobs.filter(j => j.status === 'assessment').length, color: 'bg-purple-500' },
      { id: 'interview', title: 'Interview', icon: <Users size={14} />, count: jobs.filter(j => j.status === 'interview').length, color: 'bg-orange-500' },
      { id: 'offer', title: 'Offer', icon: <Trophy size={14} />, count: jobs.filter(j => j.status === 'offer').length, color: 'bg-green-500' },
  ];

  const handleDragStart = (e: React.DragEvent, id: string) => {
      setDraggedJobId(id);
      e.dataTransfer.effectAllowed = "move";
      // Transparent drag image hack
      const img = new Image();
      img.src = 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';
      e.dataTransfer.setDragImage(img, 0, 0);
  };

  const handleDragOver = (e: React.DragEvent) => {
      e.preventDefault(); 
      e.dataTransfer.dropEffect = "move";
  };

  const handleDrop = (e: React.DragEvent, status: Job['status']) => {
      e.preventDefault();
      if (draggedJobId) {
          onToggleStatus(draggedJobId, status);
          setDraggedJobId(null);
      }
  };

  return (
    <div className="flex gap-6 overflow-x-auto w-full pb-8 items-start h-full scrollbar-hide px-6">

      {/* Spacer removed here to ensure left alignment */}

      {columns.map(col => {
            const colJobs = jobs.filter(j => j.status === col.id);
            return (
                <div 
                    key={col.id}
                    className="flex flex-col min-w-[340px] max-w-[340px] h-full rounded-[24px] bg-[#f5f5f7]/60 dark:bg-[#1C1C1E]/60 border border-white/50 dark:border-white/5 backdrop-blur-xl transition-colors ring-1 ring-black/5"
                    onDragOver={handleDragOver}
                    onDrop={(e) => handleDrop(e, col.id)}
                >
                    <div className="flex items-center justify-between p-5 mb-0 shrink-0 sticky top-0 bg-transparent z-10">
                        <div className="flex items-center gap-2">
                             <div className={`w-2 h-2 rounded-full ${col.color}`}></div>
                             <h3 className="font-bold text-[15px] text-[#1d1d1f] dark:text-white tracking-tight">
                                {col.title}
                             </h3>
                        </div>
                        <span className="text-[11px] font-bold text-[#86868b] dark:text-[#98989D] bg-white dark:bg-[#2C2C2E] px-2.5 py-1 rounded-full shadow-sm border border-black/5 dark:border-white/5">{col.count}</span>
                    </div>

                    <div className="flex-1 space-y-3 overflow-y-auto px-4 pb-4 custom-scrollbar">
                        {colJobs.length === 0 && (
                            <div className="h-32 border-2 border-dashed border-[#d2d2d7]/50 dark:border-[#38383A] rounded-2xl flex flex-col items-center justify-center gap-2 group cursor-default">
                                <div className="p-3 bg-gray-50 dark:bg-white/5 rounded-full text-gray-300 dark:text-gray-600 group-hover:text-gray-400 transition-colors">
                                    <Plus size={20} />
                                </div>
                                <span className="text-[11px] text-[#86868b] dark:text-[#98989D] font-medium">Empty Stage</span>
                            </div>
                        )}
                        {colJobs.map(job => (
                            <div
                                key={job.id}
                                draggable
                                onDragStart={(e) => handleDragStart(e, job.id)}
                                className={`cursor-grab active:cursor-grabbing transition-all duration-200 ${draggedJobId === job.id ? 'opacity-30 scale-95 rotate-3 grayscale' : 'hover:scale-[1.02] hover:-translate-y-1'}`}
                            >
                                <JobCard 
                                    job={job} 
                                    onOpenDetail={onOpenDetail}
                                    onToggleStatus={(id, st) => onToggleStatus(id, st)} 
                                    onDelete={onDelete} 
                                    isKanban={true}
                                />
                            </div>
                        ))}
                    </div>
                </div>
            );
      })}

      {/* Trailing padding */}
      <div className="shrink-0 w-6"></div>
    </div>
  );
};

export default KanbanBoard;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Bold, Italic, List, BookOpen, Trash, Sparkles, CheckCircle2, Book, MessageCircle, HelpCircle, ChevronRight, Wand2, Layout, Maximize2, Minimize2, RotateCcw, RotateCw, Pin, AlertTriangle, X, Type, Underline, Strikethrough, AlignLeft, AlignCenter, AlignRight, AlignJustify, ListOrdered, Indent, Outdent, Heading1, Heading2, Heading3, Link as LinkIcon, Unlink, Minus, Eraser, Printer, Quote, MessageSquarePlus, ZoomIn, ZoomOut, ChevronDown, Highlighter, Image, Palette } from 'lucide-react';
import { saveCV, getCV, saveJobCV } from '../services/firebase';
import { Job } from '../types';
import { USER_PROFILE } from '../constants';

interface CVEditorProps {
    targetJob?: Job | null;
    allJobs?: Job[]; 
}

const CVEditor: React.FC<CVEditorProps> = ({ targetJob, allJobs = [] }) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const [lastSaved, setLastSaved] = useState<string>('');
  const [zoomLevel, setZoomLevel] = useState(100);
  const [foundKeywords, setFoundKeywords] = useState<Set<string>>(new Set());
  const [activeSidebarTab, setActiveSidebarTab] = useState<'strategy' | 'keywords' | 'snippets'>('strategy');

  // SURGICAL PINS
  const [pinnedItems, setPinnedItems] = useState<string[]>([]);

  const keywords = useMemo(() => targetJob?.analysis?.matchedKeywords || [], [targetJob]);

  const highValueOpportunityCount = useMemo(() => {
      return allJobs.filter(j => (j.analysis?.score || 0) > 85 && j.status === 'new').length;
  }, [allJobs]);

  const scanKeywords = useCallback(() => {
    if (!editorRef.current || keywords.length === 0) return;
    const text = editorRef.current.innerText.toLowerCase();
    const found = new Set<string>();
    keywords.forEach(kw => {
        if (text.toLowerCase().includes(kw.toLowerCase())) found.add(kw);
    });
    setFoundKeywords(found);
  }, [keywords]);

  useEffect(() => {
    const loadContent = async () => {
        let content = "";
        if (targetJob) {
            content = targetJob.tailoredCv || await getCV();
        } else {
            content = await getCV();
        }

        if (editorRef.current) {
            editorRef.current.innerHTML = content || `
                <h1 style="font-size: 24pt; font-family: 'Arial', sans-serif; font-weight: 700; margin-bottom: 4pt; color: #000;">Vyom Pathroliya</h1>
                <p style="font-size: 11pt; font-family: 'Arial', sans-serif; margin-bottom: 12pt; color: #444;">Senior UX Designer • Edinburgh, UK • vyom@example.com</p>
                <h2 style="font-size: 14pt; font-family: 'Arial', sans-serif; font-weight: 700; border-bottom: 1px solid #ccc; padding-bottom: 4pt; margin-top: 16pt; margin-bottom: 8pt;">Experience</h2>
                <p style="font-size: 11pt; font-family: 'Arial', sans-serif;"><strong>Senior UX Designer</strong> | Intact Insurance</p>
            `;
            setLastSaved('Ready');
            scanKeywords();
        }
    };
    loadContent();
  }, [targetJob?.id, scanKeywords]);

  const saveContent = useCallback(async () => {
    if (!editorRef.current) return;
    const html = editorRef.current.innerHTML;
    if (targetJob) {
        await saveJobCV(targetJob.id, html);
    } else {
        await saveCV(html);
    }
    const now = new Date();
    setLastSaved(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    scanKeywords();
  }, [targetJob, scanKeywords]);

  useEffect(() => {
      const handleInput = () => {
          const timeoutId = setTimeout(() => saveContent(), 1000);
          return () => clearTimeout(timeoutId);
      };
      const el = editorRef.current;
      el?.addEventListener('input', handleInput);
      return () => el?.removeEventListener('input', handleInput);
  }, [saveContent]);

  const execCmd = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    if (editorRef.current) editorRef.current.focus();
    saveContent();
  };

  const handleComment = () => {
     // Simulate Google Docs comment by highlighting
     execCmd('backColor', '#fff0b3'); 
  };

  const insertLink = useCallback(() => {
    const url = prompt('Enter URL:');
    if (url) execCmd('createLink', url);
  }, []);

  const insertSnippet = (content: string) => {
      if (editorRef.current) {
          editorRef.current.focus();
          document.execCommand('insertHTML', false, `<p>${content}</p>`);
          saveContent();
      }
  };

  const togglePin = (content: string) => {
      setPinnedItems(prev => {
          if (prev.includes(content)) return prev.filter(p => p !== content);
          return [...prev, content];
      });
  };

  const ToolBtn = ({ icon: Icon, cmd, val, title, label, active }: { icon: any, cmd?: string, val?: string, title: string, label?: string, active?: boolean }) => (
      <button 
        onClick={() => cmd && execCmd(cmd, val)} 
        className={`p-1.5 rounded-[4px] text-[#444746] transition-colors flex items-center gap-1 hover:bg-[#1d1d1f]/5 ${active ? 'bg-[#d3e3fd] text-[#041e49]' : ''}`} 
        title={title}
      >
          <Icon size={18} strokeWidth={2} />
          {label && <span className="text-[12px] font-medium">{label}</span>}
      </button>
  );

  return (
    <div className="flex flex-col h-full bg-[#F9FBFD] dark:bg-[#0C0C0C] relative w-full">

        {/* GOOGLE DOCS STYLE TOOLBAR */}
        <div className="w-[98%] mx-auto mt-2 bg-[#EDF2FA] dark:bg-[#1E1E1E] rounded-full px-4 py-2 flex items-center gap-2 shadow-sm shrink-0 z-40 overflow-x-auto no-scrollbar">

            <div className="flex items-center gap-1 pr-2 border-r border-[#c7c7c7] dark:border-gray-700">
                 <ToolBtn icon={RotateCcw} cmd="undo" title="Undo" />
                 <ToolBtn icon={RotateCw} cmd="redo" title="Redo" />
                 <ToolBtn icon={Printer} title="Print" />
                 <ToolBtn icon={Eraser} cmd="removeFormat" title="Paint Format" />
            </div>

            <div className="flex items-center gap-2 px-2 border-r border-[#c7c7c7] dark:border-gray-700">
                <div className="flex items-center bg-white dark:bg-[#2C2C2E] rounded-md px-2 py-1 cursor-pointer hover:bg-gray-50 border border-transparent hover:border-gray-200">
                    <span className="text-xs font-medium text-gray-600 dark:text-gray-300 mr-2">100%</span>
                    <ChevronDown size={12} className="text-gray-500"/>
                </div>
            </div>

            <div className="flex items-center gap-2 px-2 border-r border-[#c7c7c7] dark:border-gray-700">
                <div className="flex items-center bg-white dark:bg-[#2C2C2E] rounded-md px-2 py-1 cursor-pointer hover:bg-gray-50 border border-transparent hover:border-gray-200 w-24 justify-between">
                    <span className="text-xs font-medium text-gray-600 dark:text-gray-300 truncate">Normal text</span>
                    <ChevronDown size={12} className="text-gray-500"/>
                </div>
                <div className="flex items-center bg-white dark:bg-[#2C2C2E] rounded-md px-2 py-1 cursor-pointer hover:bg-gray-50 border border-transparent hover:border-gray-200 w-20 justify-between">
                    <span className="text-xs font-medium text-gray-600 dark:text-gray-300 truncate">Arial</span>
                    <ChevronDown size={12} className="text-gray-500"/>
                </div>
                <div className="w-px h-4 bg-gray-300"></div>
                <ToolBtn icon={Minus} title="Decrease Font Size" />
                <div className="px-1 text-xs font-medium text-gray-600 dark:text-gray-300 bg-white dark:bg-[#2C2C2E] rounded px-2 py-1">11</div>
                <ToolBtn icon={Plus} title="Increase Font Size" />
            </div>

            <div className="flex items-center gap-1 px-2 border-r border-[#c7c7c7] dark:border-gray-700">
                <ToolBtn icon={Bold} cmd="bold" title="Bold" />
