export default App;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Bold, Italic, List, BookOpen, Trash, Sparkles, CheckCircle2, Book, MessageCircle, HelpCircle, ChevronRight, Wand2, Layout, Maximize2, Minimize2, RotateCcw, RotateCw, Pin, AlertTriangle, X, Type, Underline, Strikethrough, AlignLeft, AlignCenter, AlignRight, AlignJustify, ListOrdered, Indent, Outdent, Heading1, Heading2, Heading3, Link as LinkIcon, Unlink, Minus, Plus, Eraser, Printer, Quote, MessageSquarePlus, ZoomIn, ZoomOut, ChevronDown, Highlighter, Image, Palette, PanelRightClose, PanelRightOpen, Menu } from 'lucide-react';
import { saveCV, getCV, saveJobCV } from '../services/firebase';
import { Job } from '../types';
import { USER_PROFILE } from '../constants';

interface CVEditorProps {
    targetJob?: Job | null;
    allJobs?: Job[]; 
}

const CVEditor: React.FC<CVEditorProps> = ({ targetJob, allJobs = [] }) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [lastSaved, setLastSaved] = useState<string>('');
  const [zoomLevel, setZoomLevel] = useState(100);
  const [fontSize, setFontSize] = useState(11);
  const [foundKeywords, setFoundKeywords] = useState<Set<string>>(new Set());
  const [activeSidebarTab, setActiveSidebarTab] = useState<'strategy' | 'keywords' | 'snippets'>('strategy');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [mobileScale, setMobileScale] = useState(1);

  const keywords = useMemo(() => targetJob?.analysis?.matchedKeywords || [], [targetJob]);

  // Handle Window Resize for Mobile Scaling
  useEffect(() => {
    const handleResize = () => {
        if (containerRef.current) {
            const containerWidth = containerRef.current.offsetWidth;
            const paperWidth = 816 + 64; // Paper width + padding
            if (containerWidth < paperWidth) {
                setMobileScale((containerWidth - 32) / 816);
            } else {
                setMobileScale(1);
            }
        }
        // Auto-close sidebar on mobile
        if (window.innerWidth < 768) {
            setIsSidebarOpen(false);
        }
    };

    window.addEventListener('resize', handleResize);
    handleResize(); // Init
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const scanKeywords = useCallback(() => {
    if (!editorRef.current || keywords.length === 0) return;
    const text = editorRef.current.innerText.toLowerCase();
    const found = new Set<string>();
    keywords.forEach(kw => {
        if (text.toLowerCase().includes(kw.toLowerCase())) found.add(kw);
    });
    setFoundKeywords(found);
  }, [keywords]);

  useEffect(() => {
    const loadContent = async () => {
        let content = "";
        if (targetJob) {
            content = targetJob.tailoredCv || await getCV();
        } else {
            content = await getCV();
        }

        if (editorRef.current) {
            editorRef.current.innerHTML = content || `
                <h1 style="font-size: 24pt; font-family: 'Arial', sans-serif; font-weight: 700; margin-bottom: 4pt; color: #000;">Vyom Pathroliya</h1>
                <p style="font-size: 11pt; font-family: 'Arial', sans-serif; margin-bottom: 12pt; color: #444;">Senior UX Designer • Edinburgh, UK • vyom@example.com</p>
                <h2 style="font-size: 14pt; font-family: 'Arial', sans-serif; font-weight: 700; border-bottom: 1px solid #ccc; padding-bottom: 4pt; margin-top: 16pt; margin-bottom: 8pt;">Experience</h2>
                <p style="font-size: 11pt; font-family: 'Arial', sans-serif;"><strong>Senior UX Designer</strong> | Intact Insurance</p>
            `;
            setLastSaved('Ready');
            scanKeywords();
        }
    };
    loadContent();
  }, [targetJob?.id, scanKeywords]);

  const saveContent = useCallback(async () => {
    if (!editorRef.current) return;
    const html = editorRef.current.innerHTML;
    if (targetJob) {
        await saveJobCV(targetJob.id, html);
    } else {
        await saveCV(html);
    }
    const now = new Date();
    setLastSaved(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    scanKeywords();
  }, [targetJob, scanKeywords]);

  useEffect(() => {
      const handleInput = () => {
          const timeoutId = setTimeout(() => saveContent(), 1000);
          return () => clearTimeout(timeoutId);
      };
      const el = editorRef.current;
      el?.addEventListener('input', handleInput);
      return () => el?.removeEventListener('input', handleInput);
  }, [saveContent]);

  const execCmd = (command: string, value: string | undefined = undefined) => {
    if (editorRef.current) editorRef.current.focus(); // Vital: Refocus before executing
    document.execCommand('styleWithCSS', false, 'true');
    document.execCommand(command, false, value);
    saveContent();
  };

  const handleColor = (command: string) => {
    if (editorRef.current) editorRef.current.focus();
    const color = prompt('Enter a hex color (e.g., #ff0000) or name:');
    if (color) execCmd(command, color);
  };

  const changeFontSize = (delta: number) => {
    if (editorRef.current) editorRef.current.focus();
    const newSize = Math.max(6, fontSize + delta);
    setFontSize(newSize);

    const selection = window.getSelection();
    if (selection && selection.rangeCount > 0) {
        // Check if selection is inside editor
        if (!editorRef.current.contains(selection.anchorNode)) return;

        const range = selection.getRangeAt(0);
        if (!range.collapsed) {
             const span = document.createElement('span');
             span.style.fontSize = `${newSize}pt`;
             range.surroundContents(span);
        } else {
             document.execCommand('fontSize', false, '3'); // Fallback to ensure *something* happens
        }
        saveContent();
    }
  };

  const handleFontFamily = (font: string) => {
    execCmd('fontName', font);
  };

  const handleComment = () => {
     execCmd('backColor', '#fff0b3'); 
  };

  const insertLink = useCallback(() => {
    if (editorRef.current) editorRef.current.focus();
    const url = prompt('Enter URL:');
    if (url) execCmd('createLink', url);
  }, []);

  const insertSnippet = (content: string) => {
      if (editorRef.current) {
          editorRef.current.focus();
          document.execCommand('insertHTML', false, `<p>${content}</p>`);
          saveContent();
          if (window.innerWidth < 768) setIsSidebarOpen(false); // Close drawer on mobile after insert
      }
  };

  // Improved ToolBtn with onMouseDown to prevent focus loss
  const ToolBtn = ({ icon: Icon, cmd, val, title, label, active, onClick }: { icon: any, cmd?: string, val?: string, title: string, label?: string, active?: boolean, onClick?: () => void }) => (
      <button 
        onMouseDown={(e) => {
            e.preventDefault(); // CRITICAL: Prevents button from stealing focus from contentEditable
            if (onClick) onClick();
            else if (cmd) execCmd(cmd, val);
        }}
        className={`p-2 rounded-md text-[#444746] dark:text-gray-300 transition-colors flex items-center justify-center gap-1 hover:bg-[#1d1d1f]/10 dark:hover:bg-white/10 ${active ? 'bg-[#d3e3fd] text-[#041e49]' : ''}`} 
        title={title}
        type="button"
      >
          <Icon size={18} strokeWidth={2} />
          {label && <span className="text-[12px] font-medium hidden sm:inline">{label}</span>}
      </button>
  );

  return (
    <div className="flex flex-col h-full bg-[#F9FBFD] dark:bg-[#0C0C0C] relative w-full overflow-hidden">

        {/* TOOLBAR */}
        <div className="w-full sm:w-[98%] mx-auto sm:mt-2 bg-[#EDF2FA] dark:bg-[#1E1E1E] sm:rounded-full border-b sm:border border-black/5 dark:border-white/5 shadow-sm shrink-0 z-40">
             <div className="px-4 py-2 flex items-center gap-2 overflow-x-auto no-scrollbar">

                {/* Mobile Menu Toggle */}
                {targetJob && (
                    <button 
                        onMouseDown={(e) => e.preventDefault()}
                        onClick={() => setIsSidebarOpen(!isSidebarOpen)} 
                        className="md:hidden p-2 mr-2 rounded-md bg-white dark:bg-[#2C2C2E] border border-gray-200 dark:border-white/10"
                    >
                        <Menu size={18} className="text-gray-600 dark:text-gray-300" />
                    </button>
                )}

                <div className="flex items-center gap-1 pr-2 border-r border-[#c7c7c7] dark:border-gray-700">
                     <ToolBtn icon={RotateCcw} cmd="undo" title="Undo" />
                     <ToolBtn icon={RotateCw} cmd="redo" title="Redo" />
                </div>

                <div className="hidden sm:flex items-center gap-2 px-2 border-r border-[#c7c7c7] dark:border-gray-700">
                    <div className="flex items-center bg-white dark:bg-[#2C2C2E] rounded-md px-2 py-1 border border-transparent hover:border-gray-200">
                        <select 
                            value={zoomLevel} 
                            onChange={(e) => setZoomLevel(parseInt(e.target.value))}
                            className="bg-transparent text-xs font-medium text-gray-600 dark:text-gray-300 outline-none w-16"
                        >
                            <option value="50">50%</option>
                            <option value="75">75%</option>
                            <option value="100">100%</option>
                        </select>
                    </div>
                </div>

                <div className="flex items-center gap-2 px-2 border-r border-[#c7c7c7] dark:border-gray-700">
                    <div className="hidden sm:flex items-center bg-white dark:bg-[#2C2C2E] rounded-md px-2 py-1 border border-transparent hover:border-gray-200 w-24">
                        <select 
                            onChange={(e) => handleFontFamily(e.target.value)}
                            className="bg-transparent text-xs font-medium text-gray-600 dark:text-gray-300 outline-none w-full"
                        >
                            <option value="Arial">Arial</option>
                            <option value="Times New Roman">Times</option>
                            <option value="Georgia">Georgia</option>
                        </select>
                    </div>
                    <ToolBtn icon={Minus} onClick={() => changeFontSize(-1)} title="Smaller" />
                    <div className="hidden sm:block px-1 text-xs font-medium text-gray-600 dark:text-gray-300 bg-white dark:bg-[#2C2C2E] rounded px-2 py-1 min-w-[24px] text-center">{fontSize}</div>
                    <ToolBtn icon={Plus} onClick={() => changeFontSize(1)} title="Larger" />
                </div>

                <div className="flex items-center gap-1 px-2 border-r border-[#c7c7c7] dark:border-gray-700">
                    <ToolBtn icon={Bold} cmd="bold" title="Bold" />
                    <ToolBtn icon={Italic} cmd="italic" title="Italic" />
                    <ToolBtn icon={Underline} cmd="underline" title="Underline" />
                    <ToolBtn icon={Palette} onClick={() => handleColor('foreColor')} title="Color" />
                </div>

                <div className="flex items-center gap-1 px-2 border-r border-[#c7c7c7] dark:border-gray-700">
                    <ToolBtn icon={List} cmd="insertUnorderedList" title="Bullet List" />
                    <ToolBtn icon={ListOrdered} cmd="insertOrderedList" title="Number List" />
                </div>
             </div>
        </div>

        {/* MAIN AREA */}
        <div className="flex-1 flex overflow-hidden relative">

            {/* SIDEBAR (Responsive) */}
            {targetJob && (
                <div className={`
                    absolute inset-y-0 left-0 z-50 w-[85%] sm:w-[300px] bg-white dark:bg-[#1E1E1E] border-r border-black/5 dark:border-white/5 flex flex-col transition-transform duration-300 shadow-2xl
                    ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
                    md:relative md:translate-x-0 md:shadow-none
                `}>
                     <div className="p-4 border-b border-black/5 dark:border-white/5 flex items-center justify-between gap-2">
                        <div className="flex gap-1 flex-1">
                            <button onClick={() => setActiveSidebarTab('strategy')} className={`flex-1 py-2 text-[11px] font-bold rounded-lg ${activeSidebarTab === 'strategy' ? 'bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400' : 'text-gray-500'}`}>Strategy</button>
                            <button onClick={() => setActiveSidebarTab('snippets')} className={`flex-1 py-2 text-[11px] font-bold rounded-lg ${activeSidebarTab === 'snippets' ? 'bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400' : 'text-gray-500'}`}>Snippets</button>
                        </div>
                        <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-2 text-gray-400"><X size={18}/></button>
                     </div>

                     <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
                         {activeSidebarTab === 'strategy' && (
                            <div className="prose prose-sm text-xs text-gray-600 dark:text-gray-300">
                                {targetJob.analysis?.strategy ? (
                                    <div className="whitespace-pre-wrap">{targetJob.analysis.strategy}</div>
                                ) : (
                                    <div className="p-4 bg-gray-50 dark:bg-white/5 rounded-lg text-center">
                                        <p>No AI strategy generated yet.</p>
                                    </div>
                                )}

                                <div className="mt-6">
                                    <h4 className="font-bold mb-2 flex items-center gap-2"><Sparkles size={12}/> AI Keywords</h4>
                                    <div className="flex flex-wrap gap-2">
                                        {keywords.map(kw => (
                                            <span key={kw} className={`text-[10px] px-2 py-1 rounded border ${foundKeywords.has(kw) ? 'bg-green-50 dark:bg-green-900/20 border-green-200 dark:border-green-800 text-green-700 dark:text-green-400 line-through opacity-50' : 'bg-gray-50 dark:bg-white/5 border-gray-200 dark:border-white/10 text-gray-700 dark:text-gray-300'}`}>{kw}</span>
                                        ))}
                                    </div>
                                </div>
                            </div>
                         )}
                         {activeSidebarTab === 'snippets' && (
                             <div className="space-y-3">
                                 {USER_PROFILE.caseStudies.map(cs => (
                                     <div key={cs.title} onClick={() => insertSnippet(cs.description)} className="p-3 border border-gray-200 dark:border-white/10 rounded-xl hover:bg-gray-50 dark:hover:bg-white/5 cursor-pointer text-xs transition-colors active:scale-95">
                                         <strong className="block mb-1 dark:text-white font-bold">{cs.title}</strong>
                                         <p className="line-clamp-3 text-gray-500 dark:text-gray-400 leading-relaxed">{cs.description}</p>
                                         <div className="mt-2 text-[10px] text-blue-500 font-bold flex items-center gap-1"><Plus size={10}/> Insert</div>
                                     </div>
                                 ))}
                             </div>
                         )}
                     </div>
                </div>
            )}

            {/* DOCUMENT CANVAS */}
            <div 
                ref={containerRef}
                className="flex-1 overflow-y-auto bg-[#F9FBFD] dark:bg-[#0C0C0C] flex justify-center p-4 sm:p-8 custom-scrollbar relative touch-pan-y"
            >
                {/* THE PAPER */}
                <div 
                    className="origin-top transition-transform duration-200 shadow-2xl" 
                    style={{ 
                        transform: `scale(${mobileScale * (zoomLevel / 100)})`,
                        height: 'fit-content' 
                    }}
                >
                    <div 
                        ref={editorRef} 
                        contentEditable 
                        role="textbox" 
                        aria-multiline="true"
                        spellCheck="false"
                        className="bg-white text-black outline-none transition-all duration-300"
                        style={{
                            width: '816px', 
                            minHeight: '1056px',
                            padding: '96px', 
                            fontSize: '11pt',
                            lineHeight: '1.5',
                            fontFamily: 'Arial, sans-serif'
                        }}
                    />
                </div>
            </div>

            {/* Overlay for mobile when sidebar is open */}
            {isSidebarOpen && targetJob && (
                <div className="absolute inset-0 bg-black/50 z-40 md:hidden" onClick={() => setIsSidebarOpen(false)}></div>
            )}
        </div>
    </div>
  );
};

export default CVEditor;

import React, { useEffect, useState, useRef } from 'react';
import { X, ExternalLink, Briefcase, Zap, FileText, Sparkles, Edit2, Save, ChevronDown, RotateCw, TrendingUp, AlertTriangle, Loader2, Paperclip, Image as ImageIcon, Trash2, ChevronUp, Link as LinkIcon, Info, Check, Calendar, CalendarCheck } from 'lucide-react';
import { Job, Attachment } from '../types';

interface JobDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  job: Job | null;
  onGenerateKit: (job: Job) => void;
  initialTab?: 'brief' | 'strategy';
  onUpdateJob?: (job: Job) => void;
  onReAnalyze?: (job: Job) => Promise<void>;
  onTailorResume?: (id: string) => void;
}

const JobDetailModal: React.FC<JobDetailModalProps> = ({ isOpen, onClose, job, onGenerateKit, initialTab = 'brief', onUpdateJob, onReAnalyze, onTailorResume }) => {
  const [activeTab, setActiveTab] = useState<'brief' | 'strategy' | 'manage'>('brief');
  const [isGeneratingKit, setIsGeneratingKit] = useState(false);

  // Edit States
  const [isEditingSummary, setIsEditingSummary] = useState(false);
  const [editedSummary, setEditedSummary] = useState('');

  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editedTitle, setEditedTitle] = useState('');

  const [isEditingCompany, setIsEditingCompany] = useState(false);
  const [editedCompany, setEditedCompany] = useState('');

  const [isEditingLocation, setIsEditingLocation] = useState(false);
  const [editedLocation, setEditedLocation] = useState('');

  const [isEditingPostedDate, setIsEditingPostedDate] = useState(false);
  const [editedPostedDate, setEditedPostedDate] = useState('');

  const notesRef = useRef<HTMLDivElement>(null);
  const [isEditingNotes, setIsEditingNotes] = useState(false); 
  const lastJobIdRef = useRef<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  useEffect(() => {
    setActiveTab(initialTab);
  }, [initialTab, isOpen, job]);

  useEffect(() => {
    if (job) {
        if (!isEditingSummary) setEditedSummary(job.summary || '');
        if (!isEditingTitle) setEditedTitle(job.title || '');
        if (!isEditingCompany) setEditedCompany(job.company || '');
        if (!isEditingLocation) setEditedLocation(job.location || '');
        if (!isEditingPostedDate) setEditedPostedDate(job.postedDate || '');

        if (notesRef.current) {
            const isDifferentJob = lastJobIdRef.current !== job.id;
            if (isDifferentJob) {
                notesRef.current.innerHTML = job.notes || '';
                lastJobIdRef.current = job.id;
            } 
            else {
                const isActive = document.activeElement === notesRef.current;
                if (!isActive && job.notes !== notesRef.current.innerHTML) {
                    notesRef.current.innerHTML = job.notes || '';
                }
            }
        }
    }
  }, [job, isEditingSummary, isEditingTitle, isEditingCompany, isEditingLocation, isEditingPostedDate]);

  useEffect(() => {
      const timer = setTimeout(() => {
          if (isEditingSummary && onUpdateJob && job && editedSummary !== job.summary) {
              onUpdateJob({ ...job, summary: editedSummary });
          }
      }, 1000); 
      return () => clearTimeout(timer);
  }, [editedSummary, isEditingSummary, job, onUpdateJob]);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [isOpen]);

  if (!isOpen || !job) return null;

  const analysis = job.analysis;
  const applyUrl = job.url && job.url !== 'Manual Entry' ? (job.url.startsWith('http') ? job.url : `https://${job.url}`) : `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;
  const showStageNotes = ['assessment', 'interview', 'offer'].includes(job.status || '');

  // Handlers
  const handleSaveTitle = () => { if (onUpdateJob && editedTitle.trim() !== job.title) onUpdateJob({ ...job, title: editedTitle }); setIsEditingTitle(false); };
  const handleSaveCompany = () => { if (onUpdateJob && editedCompany.trim() !== job.company) onUpdateJob({ ...job, company: editedCompany }); setIsEditingCompany(false); };
  const handleSaveLocation = () => { if (onUpdateJob && editedLocation.trim() !== job.location) onUpdateJob({ ...job, location: editedLocation }); setIsEditingLocation(false); };
  const handleSavePostedDate = () => { if (onUpdateJob && editedPostedDate.trim() !== job.postedDate) onUpdateJob({ ...job, postedDate: editedPostedDate }); setIsEditingPostedDate(false); };

  const handleStatusChange = (e: React.ChangeEvent<HTMLSelectElement>) => { if (onUpdateJob) onUpdateJob({ ...job, status: e.target.value as Job['status'] }); };
  const handleReAnalyzeClick = async () => { if (onReAnalyze) { setIsAnalyzing(true); await onReAnalyze(job); setIsAnalyzing(false); } };
  const handleGenerateKitClick = async () => { setIsGeneratingKit(true); await onGenerateKit(job); setIsGeneratingKit(false); };
  const handleNotesUpdate = () => { if (notesRef.current && onUpdateJob) { const newNotes = notesRef.current.innerHTML; if (newNotes !== job.notes) onUpdateJob({ ...job, notes: newNotes }); } };
  const handleStageNotesUpdate = (e: React.ChangeEvent<HTMLTextAreaElement>) => { if (onUpdateJob) onUpdateJob({ ...job, stageNotes: e.target.value }); };
  const handleNotesBlur = () => { setIsEditingNotes(false); handleNotesUpdate(); };

  const handleInterviewDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const date = new Date(e.target.value);
      if (onUpdateJob && !isNaN(date.getTime())) {
          onUpdateJob({ ...job, interviewDate: date.getTime() });
      } else if (onUpdateJob && e.target.value === '') {
          onUpdateJob({ ...job, interviewDate: undefined });
      }
  };

  const getGoogleCalendarUrl = () => {
    if (!job.interviewDate) return '';
    const start = new Date(job.interviewDate);
    const end = new Date(start.getTime() + 60 * 60 * 1000); // 1 hour duration
    const format = (d: Date) => d.toISOString().replace(/-|:|\.\d\d\d/g, "");

    const title = encodeURIComponent(`Interview: ${job.title} at ${job.company}`);
    const details = encodeURIComponent(`Role: ${job.title}\nCompany: ${job.company}\n\nStage Notes:\n${job.stageNotes || ''}\n\nNotes:\n${job.notes || ''}`);
    const location = encodeURIComponent(job.location);

    return `https://www.google.com/calendar/render?action=TEMPLATE&text=${title}&details=${details}&location=${location}&dates=${format(start)}/${format(end)}`;
  };

  const handleNotesPaste = async (e: React.ClipboardEvent) => {
    const items = e.clipboardData.items;
    for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
            e.preventDefault();
            const blob = items[i].getAsFile();
            if (blob) {
                const reader = new FileReader();
                reader.onload = (ev) => {
                    const imgHtml = `<img src="${ev.target?.result}" style="max-width: 100%; border-radius: 8px; margin: 10px 0;" />`;
                    document.execCommand('insertHTML', false, imgHtml);
                    handleNotesUpdate();
                };
                reader.readAsDataURL(blob);
            }
            return;
        }
    }
  };

  const interviewDateValue = job.interviewDate 
    ? new Date(job.interviewDate - (new Date().getTimezoneOffset() * 60000)).toISOString().slice(0, 16) 
    : '';

  // Render the management controls (Status, Interview, Resume)
  const renderManagementPanel = () => (
      <div className="flex flex-col gap-8 h-full">
          <div className="bg-white dark:bg-[#1C1C1E] p-1 rounded-2xl shadow-sm border border-gray-200 dark:border-white/5">
              <div className="p-4 border-b border-gray-100 dark:border-white/5">
                  <label className="text-[10px] font-bold uppercase tracking-widest text-gray-400 mb-2 block">Current Status</label>
                  <div className="relative">
                      <select value={job.status || 'new'} onChange={handleStatusChange} className="w-full appearance-none bg-gray-50 dark:bg-black/20 px-4 py-3 rounded-xl font-bold text-sm text-apple-text dark:text-white cursor-pointer outline-none">
                          <option value="saved">Saved</option>
                          <option value="applied">Applied</option>
                          <option value="interview">Interview</option>
                          <option value="offer">Offer</option>
                          <option value="archived">Archived</option>
                      </select>
                      <ChevronDown size={14} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" />
                  </div>
              </div>
              <div className="p-4 flex items-center justify-between">
                   <div>
                      <span className="text-[10px] font-bold uppercase tracking-widest text-gray-400 block mb-1">Match Score</span>
                      <span className={`text-2xl font-bold tracking-tight ${analysis?.score >= 80 ? 'text-green-600' : 'text-apple-text dark:text-white'}`}>{analysis?.score || 0}%</span>
                   </div>
                   <button onClick={handleReAnalyzeClick} className={`p-2 rounded-lg bg-gray-100 dark:bg-white/5 text-apple-blue ${isAnalyzing ? 'animate-spin' : ''}`}>
                      <RotateCw size={16} />
                   </button>
              </div>
          </div>

          <button onClick={() => onTailorResume?.(job.id)} className="w-full py-4 bg-apple-text dark:bg-white text-white dark:text-black text-sm font-bold rounded-xl hover:scale-[1.02] active:scale-[0.98] transition-all shadow-lg flex items-center justify-center gap-2">
              <Sparkles size={16} /> Open Resume Studio
          </button>

          <div className="space-y-3">
               <span className="text-[10px] font-bold uppercase tracking-widest text-gray-400 block">Interview Schedule</span>
               <div className="relative">
                   <input 
                      type="datetime-local" 
                      value={interviewDateValue}
                      onChange={handleInterviewDateChange}
                      className="w-full px-4 py-3 bg-white dark:bg-[#1C1C1E] border border-gray-200 dark:border-white/10 rounded-xl text-sm font-medium text-apple-text dark:text-white outline-none focus:ring-2 focus:ring-apple-blue"
                   />
                   <Calendar className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" size={16} />
               </div>
               {job.interviewDate && (
                   <a 
                       href={getGoogleCalendarUrl()} 
                       target="_blank" 
                       rel="noreferrer"
                       className="w-full py-2.5 bg-white dark:bg-[#1C1C1E] border border-gray-200 dark:border-white/10 text-apple-text dark:text-white text-xs font-bold rounded-xl flex items-center justify-center gap-2 hover:bg-gray-50 dark:hover:bg-white/5 transition-colors"
                   >
                       <CalendarCheck size={14} /> Add to Google Calendar
                   </a>
               )}
          </div>

          <div className="space-y-6 pt-4 border-t border-gray-200 dark:border-white/5">
              <div>
                  <span className="text-[10px] font-bold uppercase tracking-widest text-gray-400 mb-1 block">Date Posted</span>
                   {isEditingPostedDate ? (
                      <input 
                          value={editedPostedDate} 
                          onChange={(e) => setEditedPostedDate(e.target.value)} 
                          onBlur={handleSavePostedDate} 
                          onKeyDown={(e) => e.key === 'Enter' && handleSavePostedDate()}
                          className="font-medium text-sm text-apple-text dark:text-white bg-transparent border-b border-apple-blue outline-none w-full" 
                          autoFocus 
                      />
                   ) : (
                      <p onClick={() => setIsEditingPostedDate(true)} className="font-medium text-sm text-apple-text dark:text-white cursor-pointer hover:text-apple-blue transition-colors">
                          {job.postedDate || 'Unknown'}
                      </p>
                   )}
              </div>
              <div>
                  <span className="text-[10px] font-bold uppercase tracking-widest text-gray-400 mb-1 block">Full Location</span>
                   {isEditingLocation ? (
                      <input 
                          value={editedLocation} 
                          onChange={(e) => setEditedLocation(e.target.value)} 
                          onBlur={handleSaveLocation} 
                          onKeyDown={(e) => e.key === 'Enter' && handleSaveLocation()}
                          className="font-medium text-sm text-apple-text dark:text-white bg-transparent border-b border-apple-blue outline-none w-full" 
                          autoFocus 
                      />
                   ) : (
                      <p onClick={() => setIsEditingLocation(true)} className="font-medium text-sm text-apple-text dark:text-white cursor-pointer hover:text-apple-blue transition-colors">
                          {job.location}
                      </p>
                   )}
              </div>
          </div>

          <div className="mt-auto pt-6 border-t border-gray-200 dark:border-white/5 md:block hidden">
              <a href={applyUrl} target="_blank" rel="noreferrer" className="flex items-center justify-center gap-2 w-full py-3 bg-apple-blue/10 text-apple-blue text-sm font-bold rounded-xl">
                  Visit Listing <ExternalLink size={14} />
              </a>
          </div>
      </div>
  );

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-0 sm:p-6" role="dialog" aria-modal="true">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-md transition-opacity" onClick={onClose}></div>

      <div className="relative bg-white dark:bg-[#1C1C1E] w-full max-w-6xl h-full sm:h-[92vh] flex flex-col shadow-2xl sm:rounded-[24px] overflow-hidden animate-in zoom-in-95 duration-300 border border-transparent dark:border-white/10 ring-1 ring-black/5">

        {/* Header - Fixed on Mobile/Desktop */}
        <div className="flex flex-col shrink-0 border-b border-gray-100 dark:border-white/5 bg-white/50 dark:bg-[#1C1C1E]/50 backdrop-blur-xl z-20">
           <div className="flex items-start justify-between px-6 sm:px-8 py-5 sm:py-8">
               <div className="flex-1 pr-4 sm:pr-6">
                    <div className="flex items-center gap-2 mb-2 flex-wrap">
                         <div className="flex items-center gap-2">
                             {isEditingCompany ? (
                                <input 
                                    value={editedCompany} 
                                    onChange={(e) => setEditedCompany(e.target.value)} 
                                    onBlur={handleSaveCompany} 
                                    className="text-sm sm:text-lg font-medium text-gray-500 bg-transparent border-b border-apple-blue outline-none max-w-[120px] sm:max-w-none" 
                                    autoFocus 
                                />
                             ) : (
                                <button onClick={() => setIsEditingCompany(true)} className="text-sm sm:text-lg font-medium text-gray-500 hover:text-apple-blue cursor-pointer transition-colors flex items-center gap-2 text-left truncate max-w-[120px] sm:max-w-none">
                                    {job.company}
                                </button>
                             )}
                         </div>
                    </div>

                    {isEditingTitle ? (
                        <input value={editedTitle} onChange={(e) => setEditedTitle(e.target.value)} onBlur={handleSaveTitle} onKeyDown={(e) => e.key === 'Enter' && handleSaveTitle()} className="text-lg sm:text-3xl font-bold tracking-tight text-apple-text dark:text-white w-full outline-none bg-transparent p-0 border-b-2 border-apple-blue" autoFocus />
                    ) : (
                        <h2 onClick={() => setIsEditingTitle(true)} className="text-lg sm:text-3xl font-bold tracking-tight text-apple-text dark:text-white leading-tight cursor-pointer hover:text-apple-blue transition-colors line-clamp-2">{job.title}</h2>
                    )}
               </div>
               <button onClick={onClose} className="w-10 h-10 shrink-0 flex items-center justify-center bg-gray-100 dark:bg-white/10 hover:bg-gray-200 dark:hover:bg-white/20 rounded-full transition-colors text-apple-text dark:text-white"><X size={20} /></button>
           </div>
        </div>

        {/* Content Body */}
        <div className="flex-1 overflow-hidden flex flex-col md:flex-row">
            {/* Left Column: Scrollable Description Area */}
            <div className={`flex-1 overflow-y-auto custom-scrollbar p-6 sm:p-8 md:p-10 bg-white dark:bg-[#1C1C1E] ${activeTab === 'manage' ? 'hidden md:block' : 'block'}`}>

                {/* Tabs */}
                <div className="flex items-center gap-1 mb-6 sm:mb-8 bg-gray-100 dark:bg-white/5 p-1 rounded-xl w-full sm:w-fit border border-gray-200 dark:border-white/5">
                    <button onClick={() => setActiveTab('brief')} className={`flex-1 sm:flex-none px-4 sm:px-6 py-2 rounded-lg text-[10px] sm:text-xs font-bold uppercase tracking-wider transition-all ${activeTab === 'brief' ? 'bg-white dark:bg-black text-black dark:text-white shadow-sm ring-1 ring-black/5' : 'text-gray-500 hover:text-black dark:hover:text-white'}`}>Overview</button>
                    <button onClick={() => { setActiveTab('strategy'); if (!analysis?.strategy) handleGenerateKitClick(); }} className={`flex-1 sm:flex-none px-4 sm:px-6 py-2 rounded-lg text-[10px] sm:text-xs font-bold uppercase tracking-wider transition-all ${activeTab === 'strategy' ? 'bg-white dark:bg-black text-black dark:text-white shadow-sm ring-1 ring-black/5' : 'text-gray-500 hover:text-black dark:hover:text-white'}`}>Strategy</button>

                    {/* Mobile Only Manage Tab */}
                    <button onClick={() => setActiveTab('manage')} className={`md:hidden flex-1 sm:flex-none px-4 sm:px-6 py-2 rounded-lg text-[10px] sm:text-xs font-bold uppercase tracking-wider transition-all ${activeTab === 'manage' ? 'bg-white dark:bg-black text-black dark:text-white shadow-sm ring-1 ring-black/5' : 'text-gray-500 hover:text-black dark:hover:text-white'}`}>Manage</button>
                </div>

                {activeTab === 'brief' ? (
                    <div className="animate-in fade-in slide-in-from-bottom-2 duration-300 space-y-8 pb-12">
                        {/* Tags */}
                        <div className="flex flex-wrap gap-2">
                            {analysis?.isHighValue && <span className="px-2.5 py-1 rounded-md text-[10px] font-bold bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 border border-emerald-100 dark:border-emerald-800">High Priority</span>}
                            {job.seniorityScore && <span className="px-2.5 py-1 bg-gray-50 dark:bg-white/5 rounded-md text-[10px] font-bold text-gray-600 dark:text-gray-300 border border-gray-100 dark:border-white/5">{job.seniorityScore} Level</span>}
                            <span className="px-2.5 py-1 bg-gray-50 dark:bg-white/5 rounded-md text-[10px] font-bold text-gray-600 dark:text-gray-300 border border-gray-100 dark:border-white/5">{job.source}</span>
                            <span className="px-2.5 py-1 bg-gray-50 dark:bg-white/5 rounded-md text-[10px] font-bold text-gray-600 dark:text-gray-300 border border-gray-100 dark:border-white/5 flex items-center gap-1"><Briefcase size={10}/> {job.location}</span>
                        </div>

                        {/* Verdict */}
                        {analysis ? (
                            <div className="bg-gray-50 dark:bg-white/5 p-5 sm:p-6 rounded-2xl border border-gray-100 dark:border-white/5">
                                <h4 className="text-[9px] font-bold text-gray-400 uppercase tracking-widest mb-2 flex items-center gap-2"><Sparkles size={10} className="text-apple-blue"/> Strategic Verdict</h4>
                                <p className="text-sm sm:text-xl text-apple-text dark:text-white font-medium leading-relaxed">{analysis.verdict}</p>
                            </div>
                        ) : (
                             <div className="p-5 sm:p-6 bg-blue-50 dark:bg-blue-900/10 rounded-2xl border border-blue-100 dark:border-blue-800/30 flex items-center gap-3">
                                <Loader2 className="text-apple-blue animate-spin" size={18} />
                                <span className="text-xs sm:text-sm font-semibold text-apple-blue">Analyzing opportunity potential...</span>
                             </div>
                        )}

                        {/* Stage Notes */}
                        {showStageNotes && (
                             <div className="bg-purple-50 dark:bg-purple-900/10 p-5 rounded-2xl border border-purple-100 dark:border-purple-800/30">
                                 <h4 className="text-[10px] font-bold text-purple-600 dark:text-purple-400 uppercase tracking-widest mb-3 flex items-center gap-2">
                                     <Zap size={12} /> Active Stage Notes
                                 </h4>
                                 <textarea
                                     value={job.stageNotes || ''}
                                     onChange={handleStageNotesUpdate}
                                     placeholder="Track interview prep, questions to ask, or offer details here..."
                                     className="w-full min-h-[100px] bg-white dark:bg-[#2C2C2E] rounded-xl p-3 text-sm text-apple-text dark:text-white outline-none border border-purple-100 dark:border-purple-800/30 focus:border-purple-400 transition-colors"
                                 />
                             </div>
                        )}

                        {/* Summary */}
                        <div>
                            <div className="flex items-center justify-between mb-3">
                                <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Role Description</h4>
                                <button onClick={() => setIsEditingSummary(!isEditingSummary)} className="text-[10px] font-bold text-apple-blue flex items-center gap-1">
                                    {isEditingSummary ? <Check size={12}/> : <Edit2 size={12}/>} {isEditingSummary ? 'Save' : 'Edit'}
                                </button>
                            </div>
                            {isEditingSummary ? (
                                <textarea value={editedSummary} onChange={(e) => setEditedSummary(e.target.value)} className="w-full h-80 p-4 border-2 border-apple-blue rounded-xl text-sm leading-relaxed outline-none dark:bg-[#2C2C2E] dark:text-white" autoFocus />
                            ) : (
                                <div className="text-gray-600 dark:text-gray-300 text-sm sm:text-[15px] leading-relaxed whitespace-pre-wrap">{job.summary}</div>
                            )}
                        </div>

                        {/* Notes */}
                        <div>
                            <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-3">Private Notes</h4>
                            <div className={`rounded-xl border bg-white dark:bg-[#2C2C2E] overflow-hidden ${isEditingNotes ? 'border-apple-blue' : 'border-gray-200 dark:border-white/10'}`}>
                                <div ref={notesRef} contentEditable onFocus={() => setIsEditingNotes(true)} onBlur={handleNotesBlur} onInput={handleNotesUpdate} onPaste={handleNotesPaste} className="min-h-[120px] p-4 text-sm outline-none prose dark:prose-invert max-w-none text-gray-600 dark:text-gray-300" data-placeholder="Add thoughts..." role="textbox" />
                            </div>
                        </div>
                    </div>
                ) : activeTab === 'strategy' ? (
                    <div className="animate-in fade-in slide-in-from-bottom-2 duration-300 pb-12">
                         {isGeneratingKit ? (
                            <div className="flex flex-col items-center justify-center h-48 text-center space-y-4">
                                <Loader2 size={32} className="text-apple-blue animate-spin"/>
                                <p className="text-xs font-medium text-gray-500">Formulating application strategy...</p>
                            </div>
                        ) : (
                            <article className="prose prose-sm md:prose-base dark:prose-invert max-w-none prose-headings:font-bold prose-headings:tracking-tight prose-li:marker:text-apple-blue text-gray-600 dark:text-gray-300">
                                <div className="whitespace-pre-wrap">{analysis?.strategy || "Strategy formulation failed."}</div>
                            </article>
                        )}
                    </div>
                ) : null}
            </div>

            {/* Mobile Management Panel (Shown when activeTab is manage) */}
            <div className={`flex-1 p-6 bg-gray-50 dark:bg-black/50 overflow-y-auto ${activeTab === 'manage' ? 'block md:hidden' : 'hidden'}`}>
                {renderManagementPanel()}
            </div>

            {/* Desktop Right Column (Hidden on mobile, always visible on desktop) */}
            <div className="hidden md:flex w-[320px] bg-gray-50 dark:bg-[#111] border-l border-gray-200 dark:border-white/5 p-8 flex-col gap-8">
                {renderManagementPanel()}
            </div>

            {/* Mobile Footer Actions (Only shown in Brief/Strategy tabs) */}
            {activeTab !== 'manage' && (
                <div className="md:hidden flex gap-2 p-4 pb-6 bg-white dark:bg-[#1C1C1E] border-t border-gray-100 dark:border-white/10 shrink-0 z-30">
                    <a href={applyUrl} target="_blank" rel="noreferrer" className="flex-1 py-3 bg-apple-blue text-white text-[13px] font-bold rounded-xl flex items-center justify-center gap-2 shadow-lg shadow-blue-500/20">
                        Visit Listing <ExternalLink size={14} />
                    </a>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

export default JobDetailModal;

import React, { useState } from 'react';
import { Job } from '../types';
import JobCard from './JobCard';
import { Bookmark, Send, Users, Trophy, ClipboardList, Plus } from 'lucide-react';

interface KanbanBoardProps {
  jobs: Job[];
  onGenerateKit: (job: Job) => void;
  onToggleStatus: (id: string, status: Job['status']) => void;
  onDelete: (id: string) => void;
  onOpenDetail: (job: Job) => void;
  onOpenAddModal: () => void;
}

const KanbanBoard: React.FC<KanbanBoardProps> = ({ jobs, onGenerateKit, onToggleStatus, onDelete, onOpenDetail, onOpenAddModal }) => {
  const [draggedJobId, setDraggedJobId] = useState<string | null>(null);

  const columns: { id: Job['status'], title: string, icon: React.ReactNode, count: number, color: string }[] = [
      { id: 'saved', title: 'Saved', icon: <Bookmark size={14} />, count: jobs.filter(j => j.status === 'saved').length, color: 'bg-gray-500' },
      { id: 'applied', title: 'Applied', icon: <Send size={14} />, count: jobs.filter(j => j.status === 'applied').length, color: 'bg-blue-500' },
      { id: 'assessment', title: 'Assessment', icon: <ClipboardList size={14} />, count: jobs.filter(j => j.status === 'assessment').length, color: 'bg-purple-500' },
      { id: 'interview', title: 'Interview', icon: <Users size={14} />, count: jobs.filter(j => j.status === 'interview').length, color: 'bg-orange-500' },
      { id: 'offer', title: 'Offer', icon: <Trophy size={14} />, count: jobs.filter(j => j.status === 'offer').length, color: 'bg-green-500' },
  ];

  const handleDragStart = (e: React.DragEvent, id: string) => {
      setDraggedJobId(id);
      e.dataTransfer.effectAllowed = "move";
      const img = new Image();
      img.src = 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';
      e.dataTransfer.setDragImage(img, 0, 0);
  };

  const handleDragOver = (e: React.DragEvent) => {
      e.preventDefault(); 
      e.dataTransfer.dropEffect = "move";
  };

  const handleDrop = (e: React.DragEvent, status: Job['status']) => {
      e.preventDefault();
      if (draggedJobId) {
          onToggleStatus(draggedJobId, status);
          setDraggedJobId(null);
      }
  };

  return (
    <div className="flex gap-4 sm:gap-6 overflow-x-auto w-full pb-8 items-start h-full scrollbar-hide px-4 sm:px-6 snap-x snap-mandatory">
      {columns.map(col => {
            const colJobs = jobs.filter(j => j.status === col.id);
            return (
                <div 
                    key={col.id}
                    className="flex flex-col min-w-[300px] sm:min-w-[340px] max-w-[340px] h-full rounded-[24px] bg-[#f5f5f7]/60 dark:bg-[#1C1C1E]/60 border border-white/50 dark:border-white/5 backdrop-blur-xl transition-colors ring-1 ring-black/5 snap-center"
                    onDragOver={handleDragOver}
                    onDrop={(e) => handleDrop(e, col.id)}
                >
                    <div className="flex items-center justify-between p-5 mb-0 shrink-0 sticky top-0 bg-transparent z-10">
                        <div className="flex items-center gap-2">
                             <div className={`w-2 h-2 rounded-full ${col.color}`}></div>
                             <h3 className="font-bold text-[15px] text-[#1d1d1f] dark:text-white tracking-tight">
                                {col.title}
                             </h3>
                        </div>
                        <span className="text-[11px] font-bold text-[#86868b] dark:text-[#98989D] bg-white dark:bg-[#2C2C2E] px-2.5 py-1 rounded-full shadow-sm border border-black/5 dark:border-white/5">{col.count}</span>
                    </div>

                    <div className="flex-1 space-y-3 overflow-y-auto px-4 pb-4 custom-scrollbar">
                        {colJobs.length === 0 && (
                            <div className="h-32 border-2 border-dashed border-[#d2d2d7]/50 dark:border-[#38383A] rounded-2xl flex flex-col items-center justify-center gap-2 group cursor-default">
                                <div className="p-3 bg-gray-50 dark:bg-white/5 rounded-full text-gray-300 dark:text-gray-600 group-hover:text-gray-400 transition-colors">
                                    <Plus size={20} />
                                </div>
                                <span className="text-[11px] text-[#86868b] dark:text-[#98989D] font-medium">Empty Stage</span>
                            </div>
                        )}
                        {colJobs.map(job => (
                            <div
                                key={job.id}
                                draggable
                                onDragStart={(e) => handleDragStart(e, job.id)}
                                className={`cursor-grab active:cursor-grabbing transition-all duration-200 ${draggedJobId === job.id ? 'opacity-30 scale-95 rotate-3 grayscale' : 'hover:scale-[1.02] hover:-translate-y-1'}`}
                            >
                                <JobCard 
                                    job={job} 
                                    onOpenDetail={onOpenDetail}
                                    onToggleStatus={(id, st) => onToggleStatus(id, st)} 
                                    onDelete={onDelete} 
                                    isKanban={true}
                                />
                            </div>
                        ))}
                    </div>
                </div>
            );
      })}
      <div className="shrink-0 w-2 sm:w-6"></div>
    </div>
  );
};

export default KanbanBoard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Job, ViewState } from './types';
import { searchAndParseJobs, analyzeJob, generateApplicationKit, enrichJob } from './services/geminiService';
import { initFirebase, subscribeToJobs, addOrUpdateJob, updateJobStatus, deleteJob, saveAnalysis, addManualJob } from './services/firebase';
import { DEFAULT_FIREBASE_CONFIG } from './constants';
import JobCard from './components/JobCard';
import StatsPanel from './components/StatsPanel';
import KanbanBoard from './components/KanbanBoard';
import CVEditor from './components/CVEditor';
import JobDetailModal from './components/JobDetailModal';
import AddLinkModal from './components/AddLinkModal';
import AppointmentsView from './components/AppointmentsView';
import { Layers, Moon, Sun, LogOut, Settings, X, Archive, Trash2, Plus, Search, ArrowDownUp, Sparkles, Radar, Filter, MapPin, Zap, Monitor, Briefcase, FileText, Home, Calendar } from 'lucide-react';

const App: React.FC = () => {
  // Navigation & Data
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.DASHBOARD);
  const [activeTab, setActiveTab] = useState<'new' | 'saved' | 'archived'>('new');
  const [allJobs, setAllJobs] = useState<Job[]>([]);
  const [targetJobId, setTargetJobId] = useState<string | null>(null);

  // Search Configuration
  const [searchRole, setSearchRole] = useState('Senior UX Designer');
  const [searchLocation, setSearchLocation] = useState('United Kingdom');
  const [isSearchSettingsOpen, setIsSearchSettingsOpen] = useState(false);
  const searchSettingsRef = useRef<HTMLDivElement>(null);

  // Pipeline Search
  const [pipelineSearch, setPipelineSearch] = useState('');

  // Filter Configuration (Dropdowns)
  const [isLocationOpen, setIsLocationOpen] = useState(false);
  const locationMenuRef = useRef<HTMLDivElement>(null);

  // VISUAL TELEMETRY (Scouting Drone)
  const [scoutState, setScoutState] = useState<'idle' | 'initializing' | 'scanning' | 'analyzing' | 'complete'>('idle');
  const [telemetryLogs, setTelemetryLogs] = useState<string[]>([]);

  // Multi-Select
  const [isSelectMode, setIsSelectMode] = useState(false);
  const [selectedJobIds, setSelectedJobIds] = useState<Set<string>>(new Set());

  // Theme State
  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
        return localStorage.getItem('theme') === 'dark' || 
               (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
    }
    return false;
  });

  // Profile Menu State
  const [isProfileMenuOpen, setIsProfileMenuOpen] = useState(false);
  const profileMenuRef = useRef<HTMLDivElement>(null);

  // Auto-Init Firebase
  const [isDbConnected] = useState(() => initFirebase(DEFAULT_FIREBASE_CONFIG));

  // Filter & Sort
  const [cityFilter, setCityFilter] = useState<string>('All');
  const [industryFilter, setIndustryFilter] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'date' | 'score'>('date');
  const [specialFilter, setSpecialFilter] = useState<'none' | 'high_value' | 'remote'>('none');

  // Status
  const [analyzingCount, setAnalyzingCount] = useState(0);

  // Modal
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [initialModalTab, setInitialModalTab] = useState<'brief' | 'strategy'>( 'brief');
  const [isAddLinkOpen, setIsAddLinkOpen] = useState(false);

  // Theme Effect
  useEffect(() => {
      if (darkMode) {
          document.documentElement.classList.add('dark');
          localStorage.setItem('theme', 'dark');
      } else {
          document.documentElement.classList.remove('dark');
          localStorage.setItem('theme', 'light');
      }
  }, [darkMode]);

  // Reset pipeline search when switching views
  useEffect(() => {
      setPipelineSearch('');
  }, [currentView]);

  // Click Outside Profile/Search/Location Menu
  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (profileMenuRef.current && !profileMenuRef.current.contains(event.target as Node)) {
              setIsProfileMenuOpen(false);
          }
          if (searchSettingsRef.current && !searchSettingsRef.current.contains(event.target as Node)) {
              setIsSearchSettingsOpen(false);
          }
          if (locationMenuRef.current && !locationMenuRef.current.contains(event.target as Node)) {
              setIsLocationOpen(false);
          }
      };
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isDbConnected) {
      const unsubscribe = subscribeToJobs((jobs) => {
        setAllJobs(jobs);
      });
      return () => unsubscribe();
    }
  }, [isDbConnected]);

  const addTelemetry = (log: string) => {
      setTelemetryLogs(prev => [...prev.slice(-5), `> ${log}`]);
  };

  const fetchJobs = async () => {
    if (!isDbConnected) return;
    setScoutState('initializing');
    setTelemetryLogs([]);
    addTelemetry(`System Initialized. User: Vyom Pathroliya`);
    await new Promise(r => setTimeout(r, 600));

    addTelemetry(`Target Protocol: ${searchRole}`);
    addTelemetry(`Geo-Fence: ${searchLocation}`);
    setScoutState('scanning');

    try {
      addTelemetry(`Triangulating salary bands...`);
      const foundJobs = await searchAndParseJobs(searchRole, searchLocation);
      addTelemetry(`Filtering low-seniority noise...`);

      const jobsToAnalyze: Job[] = [];
      for (const job of foundJobs) {
        const docId = `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);
        const existing = allJobs.find(j => j.id === docId);
        const jobWithTimestamp = { ...job, scoutedAt: Date.now() };
        await addOrUpdateJob(jobWithTimestamp);
        if (!existing || !existing.analysis) {
           jobsToAnalyze.push({ ...jobWithTimestamp, id: docId });
        }
      }

      if (jobsToAnalyze.length > 0) {
          setScoutState('analyzing');
          addTelemetry(`Cross-referencing Fintech keywords...`);
          addTelemetry(`Analyzing commute risk factors...`);
          await analyzeNewJobs(jobsToAnalyze);
      } else {
          addTelemetry(`No new un-analyzed targets.`);
      }

      addTelemetry(`Mission Complete.`);
      await new Promise(r => setTimeout(r, 800));
      setScoutState('idle');

    } catch (error) { 
        console.error(error); 
        addTelemetry(`ERR: Signal Lost.`);
        setTimeout(() => setScoutState('idle'), 2000);
    }
  };

  const analyzeNewJobs = async (jobs: Job[]) => {
      setAnalyzingCount(prev => prev + jobs.length);
      for (const job of jobs) {
        try {
            addTelemetry(`Analyzing fit: ${job.company}...`);
            const analysis = await analyzeJob(job);
            await saveAnalysis(job.id, analysis);
        } catch (e) {
            console.error(`Analysis failed for job ${job.id}`, e);
        } finally {
            setAnalyzingCount(prev => Math.max(0, prev - 1));
            // Artificial delay to make the telemetry readable (Game Design)
            await new Promise(resolve => setTimeout(resolve, 600)); 
        }
      }
      setAnalyzingCount(0);
  };

  const handleOpenDetail = (job: Job, tab: 'brief' | 'strategy' = 'brief') => {
    setSelectedJob(job);
    setInitialModalTab(tab);
    setModalOpen(true);
  };

  const handleUpdateJob = async (updatedJob: Job) => {
      await addOrUpdateJob(updatedJob);
      if (selectedJob && selectedJob.id === updatedJob.id) {
          setSelectedJob(updatedJob);
      }
  };

  const handleReAnalyzeJob = async (job: Job) => {
      try {
          const analysis = await analyzeJob(job);
          await saveAnalysis(job.id, analysis);
          const updatedJob = { ...job, analysis };
          setSelectedJob(updatedJob);
          setAllJobs(prev => prev.map(j => j.id === job.id ? updatedJob : j));
      } catch (e) {
          console.error("Re-analysis failed", e);
      }
  };

  const handleGenerateKit = async (job: Job) => {
    if (!job.analysis) return;
    const content = await generateApplicationKit(job, job.analysis);
    const updatedAnalysis = { ...job.analysis, strategy: content };
    await saveAnalysis(job.id, updatedAnalysis);
  };

  const toggleJobStatus = (jobId: string, currentStatus: Job['status']) => {
    let newStatus: Job['status'] = 'saved';
    if (currentStatus === 'new') newStatus = 'saved';
    else if (currentStatus === 'saved') newStatus = 'new'; 
    else if (currentStatus === 'archived') newStatus = 'new';
    updateJobStatus(jobId, newStatus!);
  };

  const handleDelete = (jobId: string) => {
    const job = allJobs.find(j => j.id === jobId);
    if (!job) return;
    if (job.status === 'archived') {
        if(confirm("Permanently delete?")) deleteJob(jobId);
    } else {
        updateJobStatus(jobId, 'archived');
    }
  };

  const handleBulkArchive = async () => {
      for (const id of selectedJobIds) {
          await updateJobStatus(id, 'archived');
      }
      setSelectedJobIds(new Set());
      setIsSelectMode(false);
  };

  const handleBulkDelete = async () => {
      if (!confirm(`Delete ${selectedJobIds.size} jobs permanently?`)) return;
      for (const id of selectedJobIds) {
          await deleteJob(id);
      }
      setSelectedJobIds(new Set());
      setIsSelectMode(false);
  };

  const toggleJobSelection = (id: string) => {
      const next = new Set(selectedJobIds);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setSelectedJobIds(next);
  };

  const handleAddManualJob = async (data: { url?: string, text?: string, title?: string, company?: string }) => {
      try {
          if (currentView !== ViewState.DASHBOARD && currentView !== ViewState.KANBAN) {
              setCurrentView(ViewState.DASHBOARD);
              setActiveTab('saved');
          }
          const placeholder = await addManualJob(data);
          if (!placeholder) return;
          setSelectedJob(placeholder);
          setModalOpen(true);
          setInitialModalTab('brief');
          setAnalyzingCount(prev => prev + 1);
          const enrichedDetails = await enrichJob(data);
          const enrichedJob = { ...placeholder, ...enrichedDetails };
          await addOrUpdateJob(enrichedJob);
          setSelectedJob(prev => (prev && prev.id === placeholder.id ? enrichedJob : prev));
          const analysis = await analyzeJob(enrichedJob);
          await saveAnalysis(enrichedJob.id, analysis);
          const analyzedJob = { ...enrichedJob, analysis };
          setSelectedJob(prev => (prev && prev.id === placeholder.id ? analyzedJob : prev));
      } catch (e) {
          console.error("Error adding manual job", e);
      } finally {
          setAnalyzingCount(prev => Math.max(0, prev - 1));
      }
  };

  const handleTailorResume = (jobId: string) => {
    setTargetJobId(jobId);
    setModalOpen(false);
    setCurrentView(ViewState.CV_EDITOR);
  };

  const jobsInCurrentTab = useMemo(() => {
    return allJobs.filter(j => {
        const status = j.status || 'new';
        if (activeTab === 'new') return status === 'new';
        if (activeTab === 'saved') return ['saved', 'applied', 'assessment', 'interview', 'offer'].includes(status);
        if (activeTab === 'archived') return status === 'archived';
        return false;
    });
  }, [allJobs, activeTab]);

  const filteredJobs = useMemo(() => {
      return jobsInCurrentTab.filter(j => {
        // City Filter
        const locMatch = cityFilter === 'All' ? true : (cityFilter === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(cityFilter.toLowerCase()));
        if (!locMatch) return false;

        // Industry Filter
        if (industryFilter) {
            const ind = j.analysis?.industry || 'Tech';
            if (ind !== industryFilter) return false;
        }

        // Special Smart Filters
        if (specialFilter === 'high_value') {
            if ((j.analysis?.score || 0) < 80) return false;
        }
        if (specialFilter === 'remote') {
            const text = (j.location + " " + j.summary + " " + (j.analysis?.workPattern || "")).toLowerCase();
            if (!text.includes('remote') && !text.includes('home') && !text.includes('wfh')) return false;
        }

        return true;
      }).sort((a, b) => {
          if (sortBy === 'score') return (b.analysis?.score || 0) - (a.analysis?.score || 0);
          return (b.scoutedAt || 0) - (a.scoutedAt || 0);
      });
  }, [jobsInCurrentTab, cityFilter, industryFilter, sortBy, specialFilter]);

  const filterOptions = ['All', 'Edinburgh', 'Glasgow', 'Remote', 'London', 'Other'];

  const targetJobForEditor = useMemo(() => {
      if (!targetJobId) return null;
      return allJobs.find(j => j.id === targetJobId) || null;
  }, [targetJobId, allJobs]);

  const pipelineJobs = useMemo(() => {
      if (!pipelineSearch.trim()) return allJobs;
      const lowerQ = pipelineSearch.toLowerCase();
      return allJobs.filter(j => 
          (j.title || '').toLowerCase().includes(lowerQ) || 
          (j.company || '').toLowerCase().includes(lowerQ)
      );
  }, [allJobs, pipelineSearch]);

  const isFixedLayout = currentView === ViewState.KANBAN || currentView === ViewState.CV_EDITOR || currentView === ViewState.APPOINTMENTS;

  return (
    <div className={`bg-[#F5F5F7] dark:bg-black font-sans transition-colors duration-300 ${isFixedLayout ? 'h-screen overflow-hidden flex flex-col' : 'min-h-screen pb-24 overflow-x-hidden'}`}>

        {/* SCOUTING DRONE OVERLAY */}
        {scoutState !== 'idle' && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-md px-4">
                <div className="w-full max-w-[480px] bg-[#1C1C1E] border border-white/10 rounded-2xl overflow-hidden shadow-2xl flex flex-col relative ring-1 ring-white/10">
                    <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-[#0071e3] to-transparent animate-shimmer"></div>
                    <div className="p-6 sm:p-8">
                        <div className="flex items-center gap-4 mb-6">
                            <div className="relative">
                                <Radar className="text-[#0071e3] animate-spin-slow" size={32} />
                                <div className="absolute inset-0 bg-[#0071e3]/30 rounded-full blur-xl animate-pulse"></div>
                            </div>
                            <div>
                                <h3 className="text-white font-bold text-lg sm:text-xl tracking-tight">Scout Drone Active</h3>
                                <p className="text-gray-400 text-[10px] sm:text-xs font-mono uppercase tracking-widest mt-1">Sector: {searchLocation}</p>
                            </div>
                        </div>
                        <div className="h-40 font-mono text-xs text-[#00ff00] bg-black rounded-xl p-4 overflow-hidden flex flex-col justify-end shadow-inner mb-6 border border-white/10">
                            {telemetryLogs.map((log, i) => (
                                <div key={i} className="animate-in fade-in slide-in-from-left-2 duration-300 whitespace-nowrap overflow-hidden text-ellipsis opacity-80">
                                    {log}
                                </div>
                            ))}
                            <div className="w-2 h-4 bg-[#00ff00] animate-pulse inline-block ml-1"></div>
